-- ===================== 0034_source_aware_costing.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0034: source-aware ingredient costing
--
-- Authority: owner decision of this date, Option A.
--   "Real purchase transactions are authoritative for ingredient costing.
--    Manual/estimated prices must NEVER be blended into the weighted-average
--    calculation with real purchases."
--
-- Requires: 0001-0033 applied.
--
-- THE DEFECT THIS CORRECTS
--   fn_ingredient_unit_cost computed sum(amount)/sum(qty_base) over EVERY
--   non-reversed ingredient_prices row in the window, filtered only by
--   ingredient, account, reversed_at and effective_date. It never looked at
--   `source`, although that column has recorded
--   'purchase' | 'manual' | 'benchmark_accepted' since 0001.
--
--   So a typed-in estimate stored as qty_base = 1 was averaged, by quantity
--   weight, against real purchases. Proven on the replica: 1,000 g at N1,000
--   plus 1,000 g at N3,000 gives N2.00/g; adding a manual estimate row shifts
--   that number by an amount the owner cannot see or reproduce from their own
--   receipts.
--
-- THE RULE THIS IMPLEMENTS
--   1. Weighted average of REAL PURCHASES inside the costing window.
--   2. Else the latest real purchase of any age -- still real evidence, and
--      never discarded in favour of a guess.
--   3. Else the latest manual/benchmark estimate, reported as an estimate.
--   4. Else NULL. Unknown stays unknown. Never zero.
--   Sources are never blended with one another at any step.
--
-- WHY A BASIS FUNCTION AND NOT AN EDIT IN PLACE
--   The page must show the customer WHICH purchases produced the number, and
--   0033's view had to mirror the window logic in SQL to do it -- a second
--   copy of the selection rule that would drift. fn_ingredient_cost_basis now
--   owns that logic once. fn_ingredient_unit_cost becomes a thin wrapper, so
--   its four callers are untouched, and the view reads provenance from the
--   same function that produced the cost. One implementation, no drift.
--
-- HISTORICAL DATA IS NOT REWRITTEN. cost_snapshots rows already stored keep
-- the values they were computed with. This changes what NEW computations
-- produce, which is the only honest treatment of a historical record.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_proc where proname = 'fn_ingredient_unit_cost') then
    raise exception '0034 preflight FAILED: fn_ingredient_unit_cost is missing.';
  end if;
  if not exists (select 1 from pg_views where viewname = 'v_recipe_line_costs') then
    raise exception '0034 preflight FAILED: 0033 must be applied first.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0034 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
  if exists (select 1 from pg_type where typname = 'ingredient_cost_basis') then
    raise exception '0034 preflight FAILED: ingredient_cost_basis already exists.';
  end if;
end
$$;

create type ingredient_cost_basis as (
  unit_cost      numeric,   -- per BASE unit, before purchase yield
  basis          text,      -- purchase_window | purchase_latest | manual | none
  purchase_count integer,
  qty_base       numeric,   -- the quantity the cost was divided by
  amount         numeric,   -- the money that quantity cost
  from_date      date,
  to_date        date
);

comment on type ingredient_cost_basis is
  'What an ingredient costs per base unit AND the evidence it came from, so a '
  'customer can reproduce the division from their own records.';

-- ----------------------------------------------------------------------------
-- The single owner of the cost-selection rule.
-- Authorization is identical to the function it replaces the internals of:
-- cost access on the business account, and the ingredient must belong to that
-- same account (blocks the mix-and-match parameter attack from 0012).
-- ----------------------------------------------------------------------------
create or replace function fn_ingredient_cost_basis(
  p_ingredient_id uuid,
  p_business_id   uuid,
  p_as_of         date default current_date)
returns ingredient_cost_basis
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_account_id uuid;
  v_ing_acct   uuid;
  v_window     integer;
  r            ingredient_cost_basis;
begin
  r.basis := 'none';

  select account_id, wavg_window_days into v_account_id, v_window
  from business_settings where business_id = p_business_id;

  if v_account_id is null then
    return r;                                     -- unknown business
  end if;

  perform fn_require_cost_access(v_account_id);   -- AUTHORIZATION

  select account_id into v_ing_acct from ingredients where id = p_ingredient_id;
  if v_ing_acct is distinct from v_account_id then
    raise exception 'Ingredient does not belong to this account'
      using errcode = '42501';
  end if;

  -- 1. REAL PURCHASES INSIDE THE WINDOW. The authoritative case.
  select sum(ip.amount) / nullif(sum(ip.qty_base), 0),
         count(*)::int, sum(ip.qty_base), sum(ip.amount),
         min(ip.effective_date), max(ip.effective_date)
    into r.unit_cost, r.purchase_count, r.qty_base, r.amount, r.from_date, r.to_date
  from ingredient_prices ip
  where ip.ingredient_id = p_ingredient_id
    and ip.account_id    = v_account_id
    and ip.source        = 'purchase'
    and ip.reversed_at is null
    and ip.effective_date <= p_as_of
    and ip.effective_date >  p_as_of - (v_window || ' days')::interval;

  if r.unit_cost is not null then
    r.basis := 'purchase_window';
    return r;
  end if;

  -- 2. THE LATEST REAL PURCHASE OF ANY AGE. Stale, but real: a genuine
  --    receipt is never discarded in favour of a typed-in guess. The page
  --    shows its date so the owner can see it is old and act.
  select ip.unit_cost, 1, ip.qty_base, ip.amount, ip.effective_date, ip.effective_date
    into r.unit_cost, r.purchase_count, r.qty_base, r.amount, r.from_date, r.to_date
  from ingredient_prices ip
  where ip.ingredient_id = p_ingredient_id
    and ip.account_id    = v_account_id
    and ip.source        = 'purchase'
    and ip.reversed_at is null
    and ip.effective_date <= p_as_of
  order by ip.effective_date desc, ip.created_at desc
  limit 1;

  if r.unit_cost is not null then
    r.basis := 'purchase_latest';
    return r;
  end if;

  -- 3. AN ESTIMATE. Only when no real purchase evidence exists at all, and
  --    always labelled so it can never masquerade as a purchase.
  select ip.unit_cost, 0, ip.qty_base, ip.amount, ip.effective_date, ip.effective_date
    into r.unit_cost, r.purchase_count, r.qty_base, r.amount, r.from_date, r.to_date
  from ingredient_prices ip
  where ip.ingredient_id = p_ingredient_id
    and ip.account_id    = v_account_id
    and ip.source in ('manual', 'benchmark_accepted')
    and ip.reversed_at is null
    and ip.effective_date <= p_as_of
  order by ip.effective_date desc, ip.created_at desc
  limit 1;

  if r.unit_cost is not null then
    r.basis := 'manual';
    return r;
  end if;

  -- 4. Nothing known. NULL, never zero.
  r := (null, 'none', null, null, null, null, null)::ingredient_cost_basis;
  return r;
end;
$$;

comment on function fn_ingredient_cost_basis(uuid, uuid, date) is
  'Owner decision (Option A): real purchases are authoritative and are never '
  'blended with manual estimates. Returns the cost AND the evidence behind it.';

-- ----------------------------------------------------------------------------
-- The existing entry point keeps its exact signature, volatility, security and
-- authorization behaviour. Its four callers -- fn_ingredient_usable_unit_cost,
-- and through it fn__recipe_cost_core, fn_variant_cost, fn_variant_problem and
-- fn_compute_variant_cost_snapshot -- are unchanged.
-- ----------------------------------------------------------------------------
create or replace function fn_ingredient_unit_cost(
  p_ingredient_id uuid,
  p_business_id   uuid,
  p_as_of         date default current_date)
returns numeric
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  return (fn_ingredient_cost_basis(p_ingredient_id, p_business_id, p_as_of)).unit_cost;
end;
$$;

-- ----------------------------------------------------------------------------
-- 0033's view re-pointed at the basis function. It previously mirrored the
-- window/reversed/as-of selection in SQL; that copy is now deleted and the
-- evidence comes from the same function that produced the cost, so the two
-- cannot disagree. Adds cost_basis so the page can say where the number
-- came from instead of implying a single receipt.
-- ----------------------------------------------------------------------------
drop view if exists v_recipe_line_costs;

create view v_recipe_line_costs with (security_invoker = on) as
select
  rl.id                              as line_id,
  rl.recipe_id,
  rl.account_id,
  r.business_id,
  rl.ingredient_id,
  rl.sub_recipe_id,
  coalesce(i.name, sr.name)          as item_name,
  i.kind                             as item_kind,
  rl.is_cost_bearing,
  rl.exclusion_reason,

  rl.qty                             as recipe_qty,
  u.code                             as recipe_unit,
  bu.code                            as base_unit,

  fn_resolve_qty_to_base(rl.ingredient_id, rl.qty, rl.unit_id) as base_qty,
  fn_ingredient_usable_unit_cost(rl.ingredient_id, r.business_id) as unit_cost,

  case when rl.is_cost_bearing then
    fn_resolve_qty_to_base(rl.ingredient_id, rl.qty, rl.unit_id)
      * fn_ingredient_usable_unit_cost(rl.ingredient_id, r.business_id)
  end                                as line_cost,

  b.qty_base                         as purchase_qty_base,
  b.amount                           as purchase_amount,
  b.to_date                          as purchase_date,
  b.purchase_count                   as purchase_count,
  b.basis                            as cost_basis,

  case
    when not rl.is_cost_bearing                                              then 'excluded'
    when rl.sub_recipe_id is not null                                        then 'sub_recipe'
    when fn_resolve_qty_to_base(rl.ingredient_id, rl.qty, rl.unit_id) is null then 'missing_conversion'
    when fn_ingredient_usable_unit_cost(rl.ingredient_id, r.business_id) is null then 'missing_price'
    else                                                                          'ok'
  end                                as problem

from recipe_lines rl
join recipes r      on r.id = rl.recipe_id and r.deleted_at is null
left join ingredients i on i.id = rl.ingredient_id
left join recipes sr    on sr.id = rl.sub_recipe_id
left join units u       on u.id = rl.unit_id
left join units bu      on bu.id = i.base_unit_id
left join lateral (
  select * from fn_ingredient_cost_basis(rl.ingredient_id, r.business_id)
) b on true;

comment on view v_recipe_line_costs is
  'Per-line cost contribution and the evidence behind each unit cost, both '
  'from the same PostgreSQL functions the engine uses. Adds no costing rule. '
  'NULL means unknown and is never rendered as zero.';

grant select on v_recipe_line_costs to authenticated;

-- ----------------------------------------------------------------------------
-- SELF-CHECK
-- ----------------------------------------------------------------------------
do $$
declare v_inv boolean; v_pol int; v_cols int;
begin
  select 'security_invoker=on' = any(reloptions) into v_inv
    from pg_class where relname = 'v_recipe_line_costs';
  if not coalesce(v_inv, false) then
    raise exception '0034 self-check FAILED: the view is not security_invoker.';
  end if;

  select count(*) into v_cols from information_schema.columns
   where table_name = 'v_recipe_line_costs';
  if v_cols <> 22 then
    raise exception '0034 self-check FAILED: view has % columns, expected 22.', v_cols;
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0034 self-check FAILED: policy count moved to %.', v_pol;
  end if;

  raise notice '0034 OK: source-aware costing live, view rebuilt with 22 columns, 116 policies unchanged.';
end
$$;

-- ===================== 0035_purchase_summary.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0035: purchase summary view
--
-- Requires: 0001-0034 applied.
--
-- WHY
--   The purchases list must show, per purchase, how many items it holds and
--   what was paid in total. Summing line amounts in the browser would put
--   money arithmetic in JavaScript, which the product rule forbids: every
--   financial figure must come from PostgreSQL.
--
--   It also avoids a real PostgREST failure. purchase_lines has TWO foreign
--   keys to both ingredients and purchases -- a composite tenant-scoped one
--   and a simple one -- so an unhinted embed returns PGRST201 "more than one
--   relationship was found" and the page silently renders zero rows. A view
--   resolves the joins in SQL and removes the ambiguity entirely.
--
-- READ ONLY. security_invoker, so RLS on purchases, purchase_lines and
-- suppliers applies to the caller exactly as it does to the tables.
-- ============================================================================

do $$
begin
  if exists (select 1 from pg_class where relname = 'v_purchase_summary') then
    raise exception '0035 preflight FAILED: v_purchase_summary already exists.';
  end if;
  if not exists (select 1 from pg_class where relname = 'purchase_lines') then
    raise exception '0035 preflight FAILED: the purchase ledger is missing.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0035 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

create view v_purchase_summary with (security_invoker = on) as
select
  p.id                                   as purchase_id,
  p.account_id,
  p.business_id,
  p.purchase_date,
  p.status,
  p.reference,
  p.reversal_reason,
  p.reverses,
  s.name                                 as supplier_name,
  count(pl.id)::int                      as line_count,
  -- NULL, not 0, when a purchase has no items yet: nothing has been paid and
  -- "N0.00" would read as a real zero-value purchase.
  case when count(pl.id) > 0 then sum(pl.amount) end as total_amount
from purchases p
left join suppliers s      on s.id = p.supplier_id
left join purchase_lines pl on pl.purchase_id = p.id and pl.account_id = p.account_id
group by p.id, p.account_id, p.business_id, p.purchase_date, p.status,
         p.reference, p.reversal_reason, p.reverses, s.name;

comment on view v_purchase_summary is
  'Per-purchase item count and total paid, summed in PostgreSQL so no money '
  'arithmetic happens in the browser. NULL total means no items recorded yet.';

grant select on v_purchase_summary to authenticated;

do $$
declare v_inv boolean;
begin
  select 'security_invoker=on' = any(reloptions) into v_inv
    from pg_class where relname = 'v_purchase_summary';
  if not coalesce(v_inv, false) then
    raise exception '0035 self-check FAILED: the view is not security_invoker.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0035 self-check FAILED: policy count moved.';
  end if;
  raise notice '0035 OK: v_purchase_summary created, security_invoker, 116 policies unchanged.';
end
$$;

-- ===================== 0036_markup.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0036: markup alongside margin
--
-- Requires: 0001-0035 applied.
--
-- WHY
--   business_settings.show_markup_alongside has existed since 0001 -- the
--   product has always intended to offer markup as well as margin -- but no
--   object ever computed it, so the setting controlled nothing.
--
--   Margin and markup answer different questions and are routinely confused:
--       margin = profit / SELLING PRICE      (what share of the price you keep)
--       markup = profit / COST               (how much you added to your cost)
--   A dish costing N850 sold at N1,500 is a 43.33% margin and a 76.47% markup.
--   Showing one and labelling it the other would misprice a menu, so markup is
--   computed here, in the same view and with the same completeness guard as
--   margin, rather than divided out in the browser.
--
--   NULL unless the recipe is complete AND a price is set AND the cost is
--   above zero. An incomplete cost yields no markup, exactly as it yields no
--   margin.
--
-- SECURITY_INVOKER IS RESTATED DELIBERATELY.
--   CREATE OR REPLACE VIEW does not preserve reloptions: omitting
--   `with (security_invoker = on)` silently RESETS it, and the view then runs
--   with the definer's rights. An earlier draft of this migration did exactly
--   that and opened a cross-tenant read on v_price_check -- tests/023 caught
--   it. A definition fingerprint does NOT detect this, because pg_views.definition
--   excludes reloptions; the self-check below asserts the option itself.
--
-- APPEND ONLY. Every existing column of v_price_check keeps its name, type and
-- position; markup_pct is added at the end. Nothing else in the definition is
-- altered -- the body below is the deployed definition, extracted verbatim.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_views where viewname = 'v_price_check') then
    raise exception '0036 preflight FAILED: v_price_check is missing.';
  end if;
  if exists (select 1 from information_schema.columns
              where table_name = 'v_price_check' and column_name = 'markup_pct') then
    raise exception '0036 preflight FAILED: markup_pct already exists.';
  end if;
  if (select count(*) from information_schema.columns
       where table_name = 'v_price_check') <> 23 then
    raise exception '0036 preflight FAILED: v_price_check has % columns, expected 23.',
      (select count(*) from information_schema.columns where table_name = 'v_price_check');
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0036 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

create or replace view v_price_check with (security_invoker = on) as
 WITH recipe_latest AS (
         SELECT DISTINCT ON (cost_snapshots.recipe_id) cost_snapshots.id,
            cost_snapshots.account_id,
            cost_snapshots.business_id,
            cost_snapshots.recipe_id,
            cost_snapshots.computed_at,
            cost_snapshots.costing_method,
            cost_snapshots.wavg_window_days,
            cost_snapshots.is_complete,
            cost_snapshots.required_inputs,
            cost_snapshots.priced_inputs,
            cost_snapshots.excluded_inputs,
            cost_snapshots.unpriced_items,
            cost_snapshots.ingredient_cost,
            cost_snapshots.packaging_cost,
            cost_snapshots.labour_cost,
            cost_snapshots.overhead_cost,
            cost_snapshots.batch_cost,
            cost_snapshots.cost_per_yield_unit,
            cost_snapshots.cost_per_portion,
            cost_snapshots.created_by,
            cost_snapshots.floor_batch_cost,
            cost_snapshots.floor_cost_per_yield_unit,
            cost_snapshots.floor_cost_per_portion,
            cost_snapshots.variant_id,
            cost_snapshots.resolved_qty,
            cost_snapshots.resolved_unit_id,
            cost_snapshots.basis_used,
            cost_snapshots.format_packaging_cost
           FROM cost_snapshots
          WHERE cost_snapshots.variant_id IS NULL
          ORDER BY cost_snapshots.recipe_id, cost_snapshots.computed_at DESC
        ), variant_latest AS (
         SELECT DISTINCT ON (cost_snapshots.variant_id) cost_snapshots.id,
            cost_snapshots.account_id,
            cost_snapshots.business_id,
            cost_snapshots.recipe_id,
            cost_snapshots.computed_at,
            cost_snapshots.costing_method,
            cost_snapshots.wavg_window_days,
            cost_snapshots.is_complete,
            cost_snapshots.required_inputs,
            cost_snapshots.priced_inputs,
            cost_snapshots.excluded_inputs,
            cost_snapshots.unpriced_items,
            cost_snapshots.ingredient_cost,
            cost_snapshots.packaging_cost,
            cost_snapshots.labour_cost,
            cost_snapshots.overhead_cost,
            cost_snapshots.batch_cost,
            cost_snapshots.cost_per_yield_unit,
            cost_snapshots.cost_per_portion,
            cost_snapshots.created_by,
            cost_snapshots.floor_batch_cost,
            cost_snapshots.floor_cost_per_yield_unit,
            cost_snapshots.floor_cost_per_portion,
            cost_snapshots.variant_id,
            cost_snapshots.resolved_qty,
            cost_snapshots.resolved_unit_id,
            cost_snapshots.basis_used,
            cost_snapshots.format_packaging_cost
           FROM cost_snapshots
          WHERE cost_snapshots.variant_id IS NOT NULL
          ORDER BY cost_snapshots.variant_id, cost_snapshots.computed_at DESC
        ), rows AS (
         SELECT r.id AS recipe_id,
            r.business_id,
            r.account_id,
            r.name,
            rv.id AS variant_id,
            f.name AS format_name,
            vl.resolved_qty,
            COALESCE(vl.is_complete, false) AS is_complete,
            vl.required_inputs,
            vl.priced_inputs,
            vl.excluded_inputs,
            COALESCE(vl.unpriced_items, '[]'::jsonb) AS unpriced_items,
            vl.floor_cost_per_portion,
            vl.cost_per_portion
           FROM recipes r
             JOIN recipe_variants rv ON rv.recipe_id = r.id AND rv.is_active
             JOIN serving_formats f ON f.id = rv.format_id
             LEFT JOIN variant_latest vl ON vl.variant_id = rv.id
          WHERE r.kind = 'dish'::recipe_kind AND r.deleted_at IS NULL
        UNION ALL
         SELECT r.id,
            r.business_id,
            r.account_id,
            r.name,
            NULL::uuid AS uuid,
            NULL::text AS text,
            NULL::numeric AS "numeric",
            COALESCE(rl.is_complete, false) AS "coalesce",
            rl.required_inputs,
            rl.priced_inputs,
            rl.excluded_inputs,
            COALESCE(rl.unpriced_items, '[]'::jsonb) AS "coalesce",
            rl.floor_cost_per_portion,
            rl.cost_per_portion
           FROM recipes r
             LEFT JOIN recipe_latest rl ON rl.recipe_id = r.id
          WHERE r.kind = 'dish'::recipe_kind AND r.deleted_at IS NULL AND NOT (EXISTS ( SELECT 1
                   FROM recipe_variants rv
                  WHERE rv.recipe_id = r.id AND rv.is_active))
        )
 SELECT x.recipe_id,
    x.business_id,
    x.account_id,
    x.name,
    ch.id AS channel_id,
    ch.name AS channel_name,
    x.is_complete,
    x.required_inputs,
    x.priced_inputs,
    x.excluded_inputs,
    x.unpriced_items,
    x.floor_cost_per_portion AS cost_floor_per_portion,
    x.cost_per_portion,
    p.price AS selling_price,
        CASE
            WHEN x.is_complete AND p.price IS NOT NULL THEN round(p.price - x.cost_per_portion, 2)
            ELSE NULL::numeric
        END AS profit,
        CASE
            WHEN x.is_complete AND p.price IS NOT NULL AND p.price > 0::numeric THEN round(100.0 * (p.price - x.cost_per_portion) / p.price, 2)
            ELSE NULL::numeric
        END AS margin_pct,
        CASE
            WHEN x.is_complete AND x.cost_per_portion IS NOT NULL AND COALESCE(ch.target_margin, bs.default_target_margin) < 100::numeric THEN ceil(x.cost_per_portion / (1::numeric - COALESCE(ch.target_margin, bs.default_target_margin) / 100.0) / bs.price_rounding_to) * bs.price_rounding_to
            ELSE NULL::numeric
        END AS recommended_price,
    COALESCE(ch.target_margin, bs.default_target_margin) AS target_margin,
    bs.price_rounding_to,
    ch.commission_pct,
    x.variant_id,
    x.format_name,
    x.resolved_qty,
        CASE
            WHEN (x.is_complete AND (p.price IS NOT NULL) AND (x.cost_per_portion > (0)::numeric))
            THEN round(((100.0 * (p.price - x.cost_per_portion)) / x.cost_per_portion), 2)
            ELSE NULL::numeric
        END AS markup_pct
   FROM rows x
     JOIN business_settings bs ON bs.business_id = x.business_id
     LEFT JOIN channels ch ON ch.business_id = x.business_id AND ch.is_active
     LEFT JOIN LATERAL ( SELECT rp.price
           FROM recipe_prices rp
          WHERE rp.recipe_id = x.recipe_id AND (rp.channel_id IS NULL OR rp.channel_id = ch.id) AND (rp.variant_id IS NULL OR rp.variant_id = x.variant_id) AND rp.effective_from <= CURRENT_DATE
          ORDER BY (rp.variant_id IS NOT NULL) DESC, rp.effective_from DESC, rp.created_at DESC
         LIMIT 1) p ON true;

do $$
declare v_cols int; v_pol int;
begin
  select count(*) into v_cols from information_schema.columns where table_name = 'v_price_check';
  if v_cols <> 24 then
    raise exception '0036 self-check FAILED: v_price_check has % columns, expected 24.', v_cols;
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'v_price_check' and column_name = 'markup_pct') then
    raise exception '0036 self-check FAILED: markup_pct was not added.';
  end if;
  if not exists (select 1 from pg_class
                  where relname = 'v_price_check'
                    and 'security_invoker=on' = any(reloptions)) then
    raise exception '0036 self-check FAILED: v_price_check lost security_invoker. '
                    'It would read across tenants.';
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0036 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0036 OK: markup_pct added, v_price_check has 24 columns, 116 policies unchanged.';
end
$$;

-- ===================== 0037_deterministic_snapshot.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0037: make "the latest cost snapshot" deterministic
--
-- Requires: 0001-0036 applied.
--
-- THE DEFECT (P1, financial)
--   Every view that resolves a recipe's current cost does
--       distinct on (recipe_id) ... order by recipe_id, computed_at desc
--   and computed_at defaults to now(), which in PostgreSQL is TRANSACTION
--   START. Two snapshots written for the same recipe inside one transaction
--   therefore carry an IDENTICAL timestamp, the ordering is a tie, and which
--   row wins is arbitrary.
--
--   Proven on the replica: a recipe costed at N850/portion, then given an
--   unpriced ingredient and recomputed in the same transaction, still reported
--   is_complete = true, a N650 profit and a 43.33% margin -- profit and margin
--   for a recipe whose cost the engine had just refused to compute. That is a
--   silent financial fallback of exactly the kind this product forbids.
--
--   It is reachable in normal use, not only in tests. fn_post_purchase writes
--   one ingredient_prices row per line inside a single transaction, and
--   ingredient_prices carries a recompute trigger (0008). A market run buying
--   two ingredients that appear in the same recipe recomputes that recipe
--   twice in one transaction and ties.
--
-- SECURITY_INVOKER IS RESTATED ON EVERY VIEW BELOW, DELIBERATELY.
--   CREATE OR REPLACE VIEW does not preserve reloptions. Omitting
--   `with (security_invoker = on)` silently RESETS it and the view then runs
--   with the definer's rights, reading across tenants. An earlier draft of
--   this migration did exactly that on all four views; tests/023 caught the
--   cross-tenant read. A definition fingerprint does NOT detect it, because
--   pg_views.definition excludes reloptions -- which is why the self-check
--   below asserts the option itself on every view touched.
--
-- THE FIX
--   cost_snapshots gains an identity column, seq, which is monotonic within
--   and across transactions. Every "latest" ordering becomes
--       order by ... computed_at desc, seq desc
--   so the newest row always wins and the result is deterministic.
--
--   Additive and non-destructive: no snapshot is altered or deleted, and the
--   costing arithmetic is untouched. Rows written before this migration are
--   assigned seq values in whatever order the table is scanned; for those,
--   computed_at remains the primary ordering exactly as before, so their
--   relative order is unchanged except where they already tied -- and where
--   they tied, no correct order existed to preserve.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_class where relname = 'cost_snapshots') then
    raise exception '0037 preflight FAILED: cost_snapshots is missing.';
  end if;
  if exists (select 1 from information_schema.columns
              where table_name = 'cost_snapshots' and column_name = 'seq') then
    raise exception '0037 preflight FAILED: cost_snapshots.seq already exists.';
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'v_price_check' and column_name = 'markup_pct') then
    raise exception '0037 preflight FAILED: 0036 must be applied first.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0037 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

alter table cost_snapshots
  add column seq bigint generated by default as identity;

comment on column cost_snapshots.seq is
  'Monotonic tie-breaker. computed_at is now(), which is transaction start, so '
  'two snapshots written in one transaction share a timestamp; seq makes '
  '"latest" deterministic. Never used in any cost calculation.';

create or replace view v_recipe_cost_current with (security_invoker = on) as
 SELECT DISTINCT ON (recipe_id) id,
    account_id,
    business_id,
    recipe_id,
    computed_at,
    costing_method,
    wavg_window_days,
    is_complete,
    required_inputs,
    priced_inputs,
    excluded_inputs,
    unpriced_items,
    ingredient_cost,
    packaging_cost,
    labour_cost,
    overhead_cost,
    batch_cost,
    cost_per_yield_unit,
    cost_per_portion,
    created_by
   FROM cost_snapshots
  ORDER BY recipe_id, computed_at DESC, seq DESC;

create or replace view v_price_check with (security_invoker = on) as
 WITH recipe_latest AS (
         SELECT DISTINCT ON (cost_snapshots.recipe_id) cost_snapshots.id,
            cost_snapshots.account_id,
            cost_snapshots.business_id,
            cost_snapshots.recipe_id,
            cost_snapshots.computed_at,
            cost_snapshots.costing_method,
            cost_snapshots.wavg_window_days,
            cost_snapshots.is_complete,
            cost_snapshots.required_inputs,
            cost_snapshots.priced_inputs,
            cost_snapshots.excluded_inputs,
            cost_snapshots.unpriced_items,
            cost_snapshots.ingredient_cost,
            cost_snapshots.packaging_cost,
            cost_snapshots.labour_cost,
            cost_snapshots.overhead_cost,
            cost_snapshots.batch_cost,
            cost_snapshots.cost_per_yield_unit,
            cost_snapshots.cost_per_portion,
            cost_snapshots.created_by,
            cost_snapshots.floor_batch_cost,
            cost_snapshots.floor_cost_per_yield_unit,
            cost_snapshots.floor_cost_per_portion,
            cost_snapshots.variant_id,
            cost_snapshots.resolved_qty,
            cost_snapshots.resolved_unit_id,
            cost_snapshots.basis_used,
            cost_snapshots.format_packaging_cost
           FROM cost_snapshots
          WHERE cost_snapshots.variant_id IS NULL
          ORDER BY cost_snapshots.recipe_id, cost_snapshots.computed_at DESC, cost_snapshots.seq DESC
        ), variant_latest AS (
         SELECT DISTINCT ON (cost_snapshots.variant_id) cost_snapshots.id,
            cost_snapshots.account_id,
            cost_snapshots.business_id,
            cost_snapshots.recipe_id,
            cost_snapshots.computed_at,
            cost_snapshots.costing_method,
            cost_snapshots.wavg_window_days,
            cost_snapshots.is_complete,
            cost_snapshots.required_inputs,
            cost_snapshots.priced_inputs,
            cost_snapshots.excluded_inputs,
            cost_snapshots.unpriced_items,
            cost_snapshots.ingredient_cost,
            cost_snapshots.packaging_cost,
            cost_snapshots.labour_cost,
            cost_snapshots.overhead_cost,
            cost_snapshots.batch_cost,
            cost_snapshots.cost_per_yield_unit,
            cost_snapshots.cost_per_portion,
            cost_snapshots.created_by,
            cost_snapshots.floor_batch_cost,
            cost_snapshots.floor_cost_per_yield_unit,
            cost_snapshots.floor_cost_per_portion,
            cost_snapshots.variant_id,
            cost_snapshots.resolved_qty,
            cost_snapshots.resolved_unit_id,
            cost_snapshots.basis_used,
            cost_snapshots.format_packaging_cost
           FROM cost_snapshots
          WHERE cost_snapshots.variant_id IS NOT NULL
          ORDER BY cost_snapshots.variant_id, cost_snapshots.computed_at DESC, cost_snapshots.seq DESC
        ), rows AS (
         SELECT r.id AS recipe_id,
            r.business_id,
            r.account_id,
            r.name,
            rv.id AS variant_id,
            f.name AS format_name,
            vl.resolved_qty,
            COALESCE(vl.is_complete, false) AS is_complete,
            vl.required_inputs,
            vl.priced_inputs,
            vl.excluded_inputs,
            COALESCE(vl.unpriced_items, '[]'::jsonb) AS unpriced_items,
            vl.floor_cost_per_portion,
            vl.cost_per_portion
           FROM recipes r
             JOIN recipe_variants rv ON rv.recipe_id = r.id AND rv.is_active
             JOIN serving_formats f ON f.id = rv.format_id
             LEFT JOIN variant_latest vl ON vl.variant_id = rv.id
          WHERE r.kind = 'dish'::recipe_kind AND r.deleted_at IS NULL
        UNION ALL
         SELECT r.id,
            r.business_id,
            r.account_id,
            r.name,
            NULL::uuid AS uuid,
            NULL::text AS text,
            NULL::numeric AS "numeric",
            COALESCE(rl.is_complete, false) AS "coalesce",
            rl.required_inputs,
            rl.priced_inputs,
            rl.excluded_inputs,
            COALESCE(rl.unpriced_items, '[]'::jsonb) AS "coalesce",
            rl.floor_cost_per_portion,
            rl.cost_per_portion
           FROM recipes r
             LEFT JOIN recipe_latest rl ON rl.recipe_id = r.id
          WHERE r.kind = 'dish'::recipe_kind AND r.deleted_at IS NULL AND NOT (EXISTS ( SELECT 1
                   FROM recipe_variants rv
                  WHERE rv.recipe_id = r.id AND rv.is_active))
        )
 SELECT x.recipe_id,
    x.business_id,
    x.account_id,
    x.name,
    ch.id AS channel_id,
    ch.name AS channel_name,
    x.is_complete,
    x.required_inputs,
    x.priced_inputs,
    x.excluded_inputs,
    x.unpriced_items,
    x.floor_cost_per_portion AS cost_floor_per_portion,
    x.cost_per_portion,
    p.price AS selling_price,
        CASE
            WHEN x.is_complete AND p.price IS NOT NULL THEN round(p.price - x.cost_per_portion, 2)
            ELSE NULL::numeric
        END AS profit,
        CASE
            WHEN x.is_complete AND p.price IS NOT NULL AND p.price > 0::numeric THEN round(100.0 * (p.price - x.cost_per_portion) / p.price, 2)
            ELSE NULL::numeric
        END AS margin_pct,
        CASE
            WHEN x.is_complete AND x.cost_per_portion IS NOT NULL AND COALESCE(ch.target_margin, bs.default_target_margin) < 100::numeric THEN ceil(x.cost_per_portion / (1::numeric - COALESCE(ch.target_margin, bs.default_target_margin) / 100.0) / bs.price_rounding_to) * bs.price_rounding_to
            ELSE NULL::numeric
        END AS recommended_price,
    COALESCE(ch.target_margin, bs.default_target_margin) AS target_margin,
    bs.price_rounding_to,
    ch.commission_pct,
    x.variant_id,
    x.format_name,
    x.resolved_qty,
        CASE
            WHEN x.is_complete AND p.price IS NOT NULL AND x.cost_per_portion > 0::numeric THEN round(100.0 * (p.price - x.cost_per_portion) / x.cost_per_portion, 2)
            ELSE NULL::numeric
        END AS markup_pct
   FROM rows x
     JOIN business_settings bs ON bs.business_id = x.business_id
     LEFT JOIN channels ch ON ch.business_id = x.business_id AND ch.is_active
     LEFT JOIN LATERAL ( SELECT rp.price
           FROM recipe_prices rp
          WHERE rp.recipe_id = x.recipe_id AND (rp.channel_id IS NULL OR rp.channel_id = ch.id) AND (rp.variant_id IS NULL OR rp.variant_id = x.variant_id) AND rp.effective_from <= CURRENT_DATE
          ORDER BY (rp.variant_id IS NOT NULL) DESC, rp.effective_from DESC, rp.created_at DESC
         LIMIT 1) p ON true;

create or replace view v_costing_blockers with (security_invoker = on) as
 WITH latest AS (
         SELECT DISTINCT ON (cost_snapshots.recipe_id) cost_snapshots.id,
            cost_snapshots.account_id,
            cost_snapshots.business_id,
            cost_snapshots.recipe_id,
            cost_snapshots.computed_at,
            cost_snapshots.costing_method,
            cost_snapshots.wavg_window_days,
            cost_snapshots.is_complete,
            cost_snapshots.required_inputs,
            cost_snapshots.priced_inputs,
            cost_snapshots.excluded_inputs,
            cost_snapshots.unpriced_items,
            cost_snapshots.ingredient_cost,
            cost_snapshots.packaging_cost,
            cost_snapshots.labour_cost,
            cost_snapshots.overhead_cost,
            cost_snapshots.batch_cost,
            cost_snapshots.cost_per_yield_unit,
            cost_snapshots.cost_per_portion,
            cost_snapshots.created_by,
            cost_snapshots.floor_batch_cost,
            cost_snapshots.floor_cost_per_yield_unit,
            cost_snapshots.floor_cost_per_portion
           FROM cost_snapshots
          ORDER BY cost_snapshots.recipe_id, cost_snapshots.computed_at DESC, cost_snapshots.seq DESC
        )
 SELECT r.account_id,
    r.business_id,
    r.id AS recipe_id,
    r.name,
    s.required_inputs,
    s.priced_inputs,
    s.excluded_inputs,
    item.value ->> 'problem'::text AS problem,
    item.value ->> 'ingredient_name'::text AS ingredient_name,
    item.value ->> 'unit'::text AS unit_code,
    item.value AS item
   FROM recipes r
     JOIN latest s ON s.recipe_id = r.id
     CROSS JOIN LATERAL jsonb_array_elements(s.unpriced_items) item(value)
  WHERE NOT s.is_complete AND r.deleted_at IS NULL;

create or replace view v_gate2_cutover with (security_invoker = on) as
 WITH latest AS (
         SELECT DISTINCT ON (cost_snapshots.recipe_id) cost_snapshots.recipe_id,
            cost_snapshots.cost_per_portion,
            cost_snapshots.computed_at,
            cost_snapshots.is_complete
           FROM cost_snapshots
          ORDER BY cost_snapshots.recipe_id, cost_snapshots.computed_at DESC, cost_snapshots.seq DESC
        )
 SELECT rv.account_id,
    rv.business_id,
    rv.id AS variant_id,
    r.id AS recipe_id,
    r.name AS recipe_name,
    f.name AS format_name,
    rv.costing_basis,
    r.portion_qty AS legacy_portion_qty,
    fn_variant_resolved_qty(rv.id) AS resolved_qty,
    s.cost_per_portion AS legacy_cost_per_portion,
    fn_variant_cost(rv.id) AS variant_cost,
    pk.pack_cost AS format_packaging_cost,
    fn_variant_problem(rv.id) AS problem,
    bs.overhead_enabled,
        CASE
            WHEN s.cost_per_portion IS NULL AND fn_variant_cost(rv.id) IS NULL THEN 'BOTH INCOMPLETE'::text
            WHEN s.cost_per_portion IS NULL OR fn_variant_cost(rv.id) IS NULL THEN 'ONE SIDE INCOMPLETE'::text
            WHEN abs(s.cost_per_portion - (fn_variant_cost(rv.id) - pk.pack_cost)) <= 0.000001 THEN
            CASE
                WHEN pk.pack_cost > 0::numeric THEN 'MATCH -- plus new format packaging'::text
                ELSE 'MATCH'::text
            END
            WHEN bs.overhead_enabled THEN 'DIFFERS -- OVERHEAD METHODOLOGY CHANGED BY 0023 (expected)'::text
            ELSE 'MISMATCH'::text
        END AS verdict
   FROM recipe_variants rv
     JOIN recipes r ON r.id = rv.recipe_id
     JOIN serving_formats f ON f.id = rv.format_id
     JOIN business_settings bs ON bs.business_id = rv.business_id
     LEFT JOIN latest s ON s.recipe_id = r.id
     CROSS JOIN LATERAL ( SELECT COALESCE(sum(spk.qty * fn_ingredient_usable_unit_cost(spk.packaging_item_id, rv.business_id)), 0::numeric) AS pack_cost
           FROM serving_format_packaging spk
          WHERE spk.format_id = rv.format_id AND spk.is_cost_bearing) pk
  WHERE r.deleted_at IS NULL;

do $$
declare v_pol int; v_bad int; v_unsafe text;
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'cost_snapshots' and column_name = 'seq') then
    raise exception '0037 self-check FAILED: seq was not added.';
  end if;

  select count(*) into v_bad from pg_views
   where schemaname = 'public'
     and viewname in ('v_recipe_cost_current','v_price_check','v_costing_blockers','v_gate2_cutover')
     and definition ~ 'computed_at DESC'
     and definition !~ 'computed_at DESC, [a-z_]*\.?seq DESC';
  if v_bad > 0 then
    raise exception '0037 self-check FAILED: % view(s) still order on computed_at alone.', v_bad;
  end if;

  -- The option, not the definition. A replaced view silently loses it.
  select string_agg(c.relname, ', ') into v_unsafe
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public'
     and c.relname in ('v_recipe_cost_current','v_price_check','v_costing_blockers','v_gate2_cutover')
     and not coalesce('security_invoker=on' = any(c.reloptions), false);
  if v_unsafe is not null then
    raise exception '0037 self-check FAILED: % lost security_invoker and would read across tenants.', v_unsafe;
  end if;

  if not exists (select 1 from information_schema.columns
                  where table_name = 'v_price_check' and column_name = 'markup_pct') then
    raise exception '0037 self-check FAILED: markup_pct was lost rebuilding v_price_check.';
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0037 self-check FAILED: policy count moved to %.', v_pol;
  end if;

  raise notice '0037 OK: seq added, 4 views deterministic and security_invoker, 116 policies unchanged.';
end
$$;

-- ===================== 0038_deterministic_functions.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0038: finish the deterministic-snapshot fix, in the functions
--
-- Requires: 0001-0037 applied.
--
-- WHAT 0037 MISSED
--   0037 made "the latest cost snapshot" deterministic in the four VIEWS that
--   resolve it. Three FUNCTIONS resolve it the same way and were not touched,
--   so they still ordered by computed_at alone. computed_at is now(), which is
--   transaction start, so two snapshots written for one recipe in a single
--   transaction tie and the winner is arbitrary.
--
--       fn_variant_cost                  -- what a sellable format costs
--       fn_compute_variant_cost_snapshot -- writes a variant snapshot
--       fn_freeze_sale_cost              -- FREEZES cost onto a sale
--
--   fn_freeze_sale_cost is the serious one. It writes the cost of goods onto a
--   sale permanently, and the schema treats frozen sale costs as immutable
--   history. A tie there does not merely display a wrong number, it records
--   one, and the record is the thing later margin reporting is built on.
--
--   Reachable exactly as in 0037: fn_post_purchase writes one ingredient_prices
--   row per line inside one transaction, and ingredient_prices carries a
--   recompute trigger, so a purchase covering two ingredients used by the same
--   recipe recomputes it twice and ties.
--
-- THE FIX
--   The same tie-breaker 0037 introduced: order by computed_at desc, seq desc.
--   Nothing else in any of the three functions is altered -- the bodies below
--   are the deployed definitions with only that ordering changed.
-- ============================================================================

do $$
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'cost_snapshots' and column_name = 'seq') then
    raise exception '0038 preflight FAILED: 0037 must be applied first (seq is missing).';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0038 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

CREATE OR REPLACE FUNCTION public.fn_variant_cost(p_variant_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v record; v_qty numeric; v_cpyu numeric; v_pack numeric;
  v_oh_rate numeric; v_oh numeric; v_problem text;
begin
  select rv.account_id, rv.business_id, rv.recipe_id, rv.format_id,
         r.yield_unit_id
    into v
    from recipe_variants rv
    join recipes r on r.id = rv.recipe_id
   where rv.id = p_variant_id;

  if v is null then return null; end if;
  perform fn_require_cost_access(v.account_id);

  v_problem := fn_variant_problem(p_variant_id);
  if v_problem is not null then return null; end if;

  v_qty := fn_variant_resolved_qty(p_variant_id);
  if v_qty is null then return null; end if;

  -- the existing engine's figure, unchanged: it already carries ingredients,
  -- sub-recipes, purchase yield, cooking yield and labour over effective yield
  select cost_per_yield_unit into v_cpyu
    from cost_snapshots
   where recipe_id = v.recipe_id
   order by computed_at desc, seq desc
   limit 1;
  if v_cpyu is null then return null; end if;

  -- D4: format packaging is consumed once per sold unit and is NOT multiplied
  -- by the resolved quantity. No rows means no cost -- a true zero, not a NULL
  -- coerced into one.
  select coalesce(sum(spk.qty * fn_ingredient_usable_unit_cost(
                        spk.packaging_item_id, v.business_id)), 0)
    into v_pack
    from serving_format_packaging spk
   where spk.format_id = v.format_id
     and spk.is_cost_bearing;

  -- D1: overhead scales with output
  v_oh_rate := fn_overhead_rate(v.business_id, v.yield_unit_id);
  if v_oh_rate is null then
    if (select overhead_enabled from business_settings where business_id = v.business_id) then
      return null;      -- enabled but unresolvable: incomplete, never zero
    end if;
    v_oh := 0;          -- genuinely disabled: a true zero
  else
    v_oh := v_oh_rate * v_qty;
  end if;

  return v_cpyu * v_qty + v_pack + v_oh;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_compute_variant_cost_snapshot(p_variant_id uuid, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v record; base cost_snapshots%rowtype;
  v_qty numeric; v_cost numeric; v_problem text; v_pack numeric;
  v_complete boolean; v_unpriced jsonb; v_id uuid;
begin
  select rv.account_id, rv.business_id, rv.recipe_id, rv.format_id,
         rv.costing_basis, r.yield_unit_id
    into v
    from recipe_variants rv
    join recipes r on r.id = rv.recipe_id
   where rv.id = p_variant_id;
  if v is null then
    raise exception 'Variant % does not exist', p_variant_id;
  end if;
  perform fn_require_cost_access(v.account_id);

  select * into base from cost_snapshots
   where recipe_id = v.recipe_id and variant_id is null
   order by computed_at desc, seq desc limit 1;
  if not found then
    raise exception 'Recipe % has no cost snapshot yet. Compute the recipe '
                    'cost before the variant cost.', v.recipe_id;
  end if;

  v_problem := fn_variant_problem(p_variant_id);
  v_qty     := fn_variant_resolved_qty(p_variant_id);
  v_cost    := fn_variant_cost(p_variant_id);

  select coalesce(sum(spk.qty * fn_ingredient_usable_unit_cost(
                        spk.packaging_item_id, v.business_id)), 0)
    into v_pack
    from serving_format_packaging spk
   where spk.format_id = v.format_id and spk.is_cost_bearing;

  -- Completeness propagates upward exactly as it does for sub-recipes: a
  -- variant is complete only if its own basis resolves AND the recipe beneath
  -- it is complete.
  v_complete := base.is_complete and v_problem is null and v_cost is not null;
  v_unpriced := coalesce(base.unpriced_items, '[]'::jsonb);
  if v_problem is not null then
    v_unpriced := v_unpriced || jsonb_build_object(
      'variant_id', p_variant_id, 'problem', v_problem);
  end if;

  insert into cost_snapshots (
      account_id, business_id, recipe_id, computed_at,
      costing_method, wavg_window_days,
      is_complete, required_inputs, priced_inputs, excluded_inputs, unpriced_items,
      ingredient_cost, packaging_cost, labour_cost, overhead_cost,
      batch_cost, cost_per_yield_unit, cost_per_portion,
      floor_batch_cost, floor_cost_per_yield_unit, floor_cost_per_portion,
      created_by,
      variant_id, resolved_qty, resolved_unit_id, basis_used, format_packaging_cost)
  values (
      v.account_id, v.business_id, v.recipe_id, now(),
      base.costing_method, base.wavg_window_days,
      v_complete, base.required_inputs, base.priced_inputs, base.excluded_inputs,
      v_unpriced,
      base.ingredient_cost, base.packaging_cost, base.labour_cost, base.overhead_cost,
      base.batch_cost, base.cost_per_yield_unit,
      v_cost,                                   -- cost per SOLD UNIT, not per portion
      base.floor_batch_cost, base.floor_cost_per_yield_unit, base.floor_cost_per_portion,
      auth.uid(),
      p_variant_id, v_qty, v.yield_unit_id, v.costing_basis, v_pack)
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.fn_freeze_sale_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s cost_snapshots%rowtype;
begin
  if new.recipe_id is null then
    new.cost_snapshot_id  := null;
    new.unit_cost_at_sale := null;
    return new;
  end if;

  if new.variant_id is not null then
    -- what was actually sold is the variant, so that is what is frozen
    select * into s
    from cost_snapshots
    where variant_id = new.variant_id
    order by computed_at desc, seq desc
    limit 1;
  else
    -- unchanged legacy path: recipe-level snapshots only
    select * into s
    from cost_snapshots
    where recipe_id = new.recipe_id and variant_id is null
    order by computed_at desc, seq desc
    limit 1;
  end if;

  -- The gate applies here too. An incomplete cost is not a cost.
  if not found or not s.is_complete or s.cost_per_portion is null then
    new.cost_snapshot_id  := null;
    new.unit_cost_at_sale := null;
  else
    new.cost_snapshot_id  := s.id;
    new.unit_cost_at_sale := s.cost_per_portion;
  end if;

  return new;
end;
$function$;

do $$
declare v_bad text; v_pol int;
begin
  select string_agg(p.proname, ', ') into v_bad
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.prokind = 'f'
     and pg_get_functiondef(p.oid) ~* 'order by computed_at desc'
     and pg_get_functiondef(p.oid) !~* 'order by computed_at desc, seq desc';
  if v_bad is not null then
    raise exception '0038 self-check FAILED: % still pick a snapshot without a tie-breaker.', v_bad;
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0038 self-check FAILED: policy count moved to %.', v_pol;
  end if;

  raise notice '0038 OK: 3 functions now tie-break on seq, 116 policies unchanged.';
end
$$;

-- ===================== 0039_costing_models.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0039: two costing models -- portion-based and format-based
--
-- Requires: 0001-0038 applied.
--
-- OWNER DECISION (Phase 4 escalation, Option A with clarification)
--   Menu Master supports TWO valid selling models, and exactly one applies to
--   any given recipe. This is NOT "portion size is optional".
--
--   MODEL 1, PORTION-BASED. The recipe produces discrete servings -- plates,
--   meals, slices, guests. The portion is the commercial unit and its size is
--   a required input.
--
--   MODEL 2, FORMAT-BASED. The recipe produces a measurable batch that the
--   business sells through its own formats -- 1 L, 1.5 L, 2.5 L, 4 L; 500 g;
--   a 6-piece pack. The FORMAT is the commercial unit. Requiring a synthetic
--   portion size merely to satisfy the engine would be inventing an input,
--   and a business selling only by format could not cost anything at all.
--
-- WHAT CHANGES
--   Only which inputs a recipe REQUIRES. A recipe with at least one active
--   sellable format (an active recipe_variant on an active serving_format) no
--   longer requires portion_qty, and no per-portion overhead projection is
--   demanded of it. Nothing else is altered.
--
-- WHAT DOES NOT CHANGE -- and did not need to
--   The format costing engine already implements the approved model exactly:
--       fn_variant_resolved_qty  the format's quantity in the recipe's yield
--                                unit, via the existing unit/conversion
--                                architecture. NULL across incompatible
--                                dimensions -- never a guess.
--       fn_variant_problem       blocks on incompatible dimensions, missing
--                                conversions and unpriced packaging.
--       fn_variant_cost          cost_per_yield_unit x resolved_qty
--                                + packaging (ONCE per sellable unit)
--                                + overhead_rate x resolved_qty
--
--   So batch economics are PROJECTED onto each format, never duplicated. One
--   recipe may carry 1 L, 1.5 L, 2.5 L and 4 L formats without four recipes
--   and without multiplying batch labour or batch overhead into each.
--
--   No dimension is hard-coded. 10 L -> 2.5 L, 10 kg -> 500 g and 100 pieces
--   -> a 6-piece pack all resolve through the same conversion architecture;
--   10 L -> 500 g resolves to NULL and blocks unless the business has itself
--   supplied a conversion making those dimensions convertible.
--
-- PROVENANCE
--   A recipe's basis is derivable and is exposed: a recipe with active
--   sellable formats is format-based, otherwise portion-based. v_recipe_basis
--   (below) states it, so no caller has to infer it.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_proc where proname = 'fn_variant_cost') then
    raise exception '0039 preflight FAILED: the variant costing engine is missing.';
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'cost_snapshots' and column_name = 'seq') then
    raise exception '0039 preflight FAILED: 0037/0038 must be applied first.';
  end if;
  if exists (select 1 from pg_views where viewname = 'v_recipe_basis') then
    raise exception '0039 preflight FAILED: v_recipe_basis already exists.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0039 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

CREATE OR REPLACE FUNCTION public.fn_compute_recipe_cost_snapshot(p_recipe_id uuid, p_as_of date DEFAULT CURRENT_DATE, p_created_by uuid DEFAULT auth.uid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r recipes%rowtype; bs business_settings%rowtype; core recipe_cost_result;
  v_overhead numeric := 0; v_oh_total numeric; v_oh_rate numeric;
  v_sold_by_format boolean;
  v_required integer; v_priced integer; v_unpriced jsonb; v_complete boolean;
  v_floor_pp numeric; v_snapshot uuid;
begin
  select * into r from recipes where id = p_recipe_id and deleted_at is null;
  if not found then raise exception 'Recipe % not found', p_recipe_id; end if;

  perform fn_require_cost_access(r.account_id);   -- AUTHORIZATION

  select * into bs from business_settings where business_id = r.business_id;
  if not found then
    raise exception 'Business settings missing for business %', r.business_id;
  end if;

  core := fn__recipe_cost_core(p_recipe_id, p_as_of, 0);

  v_required := core.required_inputs;
  v_priced   := core.priced_inputs;
  v_unpriced := core.unpriced_items;
  v_complete := core.is_complete;

  -- MODEL 1 vs MODEL 2 (owner decision, Phase 4 escalation).
  -- A recipe sold through its own business-defined formats does not need a
  -- portion size: the FORMAT is the commercial unit, and fn_variant_cost
  -- allocates the batch economics to each format. A recipe with no active
  -- sellable format is portion-based and still requires one. This is not
  -- "portion is optional" -- exactly one basis applies, and which one is
  -- determined here rather than guessed.
  select exists (
    select 1
      from recipe_variants rv
      join serving_formats sf on sf.id = rv.format_id
     where rv.recipe_id = p_recipe_id
       and rv.is_active
       and sf.is_active
  ) into v_sold_by_format;

  if bs.overhead_enabled then
    v_required := v_required + 1;
    select sum(monthly_cost) into v_oh_total
    from overhead_items
    where business_id = r.business_id and is_active and monthly_cost is not null;

    -- D1: the overhead ITEMS are the config question. Whether a BASIS exists
    -- is a separate question, with its own problem code below. The deprecated
    -- per-portion denominator is retained on the table but no longer read.
    if v_oh_total is null
       or exists (select 1 from overhead_items
                   where business_id = r.business_id and is_active and monthly_cost is null)
    then
      v_complete := false;
      v_unpriced := v_unpriced || jsonb_build_object(
        'recipe_id', p_recipe_id, 'business_id', r.business_id,
        'problem', 'missing_overhead_config');
      v_overhead := null;
    elsif bs.overhead_basis_qty is null or bs.overhead_basis_unit_id is null then
      -- overhead is enabled but no basis has been declared. Report it by name.
      -- DO NOT fall back to the old denominator: silently switching methodology
      -- is exactly what this migration exists to prevent.
      v_complete := false;
      v_unpriced := v_unpriced || jsonb_build_object(
        'recipe_id', p_recipe_id, 'business_id', r.business_id,
        'problem', 'missing_overhead_basis');
      v_overhead := null;
    else
      v_oh_rate := fn_overhead_rate(r.business_id, r.yield_unit_id);
      if v_oh_rate is null then
        -- the basis exists but cannot be expressed in this recipe's yield unit:
        -- a litre basis cannot allocate to a recipe sold by the piece. No
        -- cross-kind conversion is invented (D1 option a).
        v_complete := false;
        v_unpriced := v_unpriced || jsonb_build_object(
          'recipe_id', p_recipe_id, 'business_id', r.business_id,
          'problem', 'overhead_basis_incompatible');
        v_overhead := null;
      elsif r.portion_qty is null then
        -- No portion size. For a PORTION-BASED recipe that is incomplete, and
        -- missing_portion_size below records it. For a FORMAT-BASED recipe it
        -- is correct: overhead is allocated per sellable format by
        -- fn_variant_cost as overhead_rate x resolved_qty, so there is no
        -- per-portion figure to compute and none is invented. The rate itself
        -- is resolvable either way -- only this projection of it is absent.
        v_overhead := null;
        if v_sold_by_format then
          v_priced := v_priced + 1;
        end if;
      else
        v_overhead := v_oh_rate * r.portion_qty;
        v_priced   := v_priced + 1;
      end if;
    end if;
  end if;

  if r.kind = 'dish' and not v_sold_by_format then
    -- MODEL 1, portion-based: the portion is the commercial unit, so its size
    -- is a required input.
    v_required := v_required + 1;
    if r.portion_qty is null then
      v_complete := false;
      v_unpriced := v_unpriced || jsonb_build_object(
        'recipe_id', p_recipe_id, 'problem', 'missing_portion_size');
    else
      v_priced := v_priced + 1;
    end if;
  end if;
  -- MODEL 2, format-based: no portion input is required and none is invented.
  -- Whether each format can actually be costed is decided per format by
  -- fn_variant_problem, which blocks on incompatible dimensions, missing
  -- conversions and unpriced packaging. A recipe can therefore be complete
  -- while one of its formats is not, which is the truth of the situation.

  if core.priced_inputs = 0 then
    v_floor_pp := null;
  elsif core.cost_per_yield_unit is not null and r.portion_qty is not null then
    v_floor_pp := core.cost_per_yield_unit * r.portion_qty + coalesce(v_overhead, 0);
  else
    v_floor_pp := null;
  end if;

  if jsonb_array_length(v_unpriced) > 0 then
    v_complete := false;
  end if;

  insert into cost_snapshots (
    account_id, business_id, recipe_id, computed_at,
    costing_method, wavg_window_days,
    is_complete, required_inputs, priced_inputs, excluded_inputs, unpriced_items,
    ingredient_cost, packaging_cost, labour_cost, overhead_cost,
    batch_cost, cost_per_yield_unit, cost_per_portion,
    floor_batch_cost, floor_cost_per_yield_unit, floor_cost_per_portion,
    created_by)
  values (
    r.account_id, r.business_id, p_recipe_id, now(),
    bs.costing_method, bs.wavg_window_days,
    v_complete, v_required, v_priced, core.excluded_inputs, v_unpriced,
    core.ingredient_cost, core.packaging_cost, core.labour_cost, v_overhead,
    case when v_complete then core.batch_cost end,
    case when v_complete then core.cost_per_yield_unit end,
    case when v_complete then v_floor_pp end,
    case when core.priced_inputs > 0 then core.batch_cost end,
    case when core.priced_inputs > 0 then core.cost_per_yield_unit end,
    v_floor_pp,
    p_created_by)
  returning id into v_snapshot;

  return v_snapshot;
end;
$function$;

-- Which model a recipe is costed under, stated rather than inferred by callers.
create view v_recipe_basis with (security_invoker = on) as
select
  r.id            as recipe_id,
  r.account_id,
  r.business_id,
  r.name,
  case when exists (
         select 1 from recipe_variants rv
         join serving_formats sf on sf.id = rv.format_id
        where rv.recipe_id = r.id and rv.is_active and sf.is_active)
       then 'format' else 'portion' end          as costing_basis,
  (select count(*) from recipe_variants rv
    join serving_formats sf on sf.id = rv.format_id
   where rv.recipe_id = r.id and rv.is_active and sf.is_active)::int as active_formats,
  r.portion_qty
from recipes r
where r.deleted_at is null;

comment on view v_recipe_basis is
  'Whether a recipe is costed per portion or per business-defined format. '
  'A recipe with at least one active sellable format is format-based and does '
  'not require a portion size.';

grant select on v_recipe_basis to authenticated;


do $$
declare v_pol int; v_unsafe text;
begin
  if not exists (select 1 from pg_views where viewname = 'v_recipe_basis') then
    raise exception '0039 self-check FAILED: v_recipe_basis was not created.';
  end if;

  -- the option, not the definition: a replaced view silently loses it
  select string_agg(c.relname, ', ') into v_unsafe
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'v'
     and c.relname = 'v_recipe_basis'
     and not coalesce('security_invoker=on' = any(c.reloptions), false);
  if v_unsafe is not null then
    raise exception '0039 self-check FAILED: % lost security_invoker.', v_unsafe;
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0039 self-check FAILED: policy count moved to %.', v_pol;
  end if;

  raise notice '0039 OK: portion/format costing models live, v_recipe_basis created, 116 policies unchanged.';
end
$$;

-- ===================== 0040_variant_identity_units.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0040: a format stated in the recipe's own unit must resolve
--
-- Requires: 0001-0039 applied.
--
-- THE DEFECT (P1)
--   fn_variant_problem decided whether a format could be costed by testing
--   units.factor_to_base itself, rather than asking fn_variant_resolved_qty.
--   Container units carry no universal factor by design -- a paint of rice and
--   a paint of beans are different weights -- so the test refused them.
--
--   That is right across DIFFERENT units and wrong when the format is stated
--   in the SAME unit the recipe yields in. piece -> piece is the identity; it
--   needs no factor. fn_variant_resolved_qty already returned the correct
--   quantity while fn_variant_problem refused the very same variant, so
--   fn_variant_cost returned NULL and the format could not be costed at all.
--
--   Reached by any business whose output is counted rather than weighed or
--   measured: 100 rolls sold in 6-piece packs, wraps sold by the wrap, bowls
--   sold by the bowl. Proven: resolved_qty = 6 while problem =
--   'capacity_unit_unconvertible'.
--
-- ROOT CAUSE
--   Two implementations of one rule. The convertibility question belongs to
--   the resolver; the problem check now asks it instead of re-deriving it, so
--   they cannot disagree again. Reason codes are unchanged, so callers and UI
--   copy keep working: 'capacity_unit_incompatible' still means the dimensions
--   differ, 'capacity_unit_unconvertible' still means no conversion exists.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_proc where proname = 'fn_variant_resolved_qty') then
    raise exception '0040 preflight FAILED: fn_variant_resolved_qty is missing.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0040 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

CREATE OR REPLACE FUNCTION public.fn_variant_problem(p_variant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v record; v_from_kind unit_kind; v_to_kind unit_kind;
  v_from_factor numeric; v_unpriced int;
begin
  select rv.account_id, rv.business_id, rv.costing_basis, rv.sellable_qty,
         rv.sellable_unit_id, rv.format_id,
         f.capacity_qty, f.capacity_unit_id,
         r.yield_unit_id, r.id as recipe_id
    into v
    from recipe_variants rv
    join serving_formats f on f.id = rv.format_id
    join recipes r on r.id = rv.recipe_id
   where rv.id = p_variant_id;

  if v is null then return 'variant_not_found'; end if;
  perform fn_require_member(v.account_id);

  select kind into v_to_kind from units where id = v.yield_unit_id;

  if v.costing_basis = 'capacity' then
    if v.capacity_qty is null or v.capacity_unit_id is null then
      return 'format_missing_capacity';
    end if;
    select kind, factor_to_base into v_from_kind, v_from_factor
      from units where id = v.capacity_unit_id;
    if v_from_kind is distinct from v_to_kind then
      return 'capacity_unit_incompatible';
    end if;
    -- ASK THE RESOLVER, do not re-derive convertibility here.
    --
    -- This previously refused whenever the format's unit had no universal
    -- factor_to_base, on the reasoning that a container unit cannot resolve.
    -- That is true across DIFFERENT units, but not when the format is stated
    -- in the SAME unit the recipe yields in: piece -> piece is the identity
    -- and needs no factor. fn_variant_resolved_qty already returned the right
    -- answer while this check refused it, so a business selling 100 rolls in
    -- 6-piece packs -- any count- or container-yield business -- was blocked
    -- from costing anything. Two implementations of one rule had drifted.
    if fn_variant_resolved_qty(p_variant_id) is null then
      return 'capacity_unit_unconvertible';
    end if;
  else
    if v.sellable_qty is null or v.sellable_unit_id is null then
      return 'missing_sellable_quantity';
    end if;
    select kind, factor_to_base into v_from_kind, v_from_factor
      from units where id = v.sellable_unit_id;
    if v_from_kind is distinct from v_to_kind then
      return 'sellable_unit_incompatible';
    end if;
    -- Same correction on the explicit-quantity basis.
    if fn_variant_resolved_qty(p_variant_id) is null then
      return 'sellable_unit_incompatible';
    end if;
  end if;

  -- a format packaging item with no price blocks the variant, exactly as an
  -- unpriced ingredient blocks the recipe
  select count(*) into v_unpriced
    from serving_format_packaging spk
   where spk.format_id = v.format_id
     and spk.is_cost_bearing
     and fn_ingredient_usable_unit_cost(spk.packaging_item_id, v.business_id) is null;
  if v_unpriced > 0 then
    return 'missing_packaging_price';
  end if;

  return null;
end;
$function$;

do $$
declare v_pol int;
begin
  if pg_get_functiondef((select oid from pg_proc where proname='fn_variant_problem' and prokind='f'))
     !~ 'fn_variant_resolved_qty' then
    raise exception '0040 self-check FAILED: fn_variant_problem still re-derives convertibility.';
  end if;
  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0040 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0040 OK: fn_variant_problem defers to the resolver, 116 policies unchanged.';
end
$$;

-- ===================== 0041_overhead_pools.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0041: overhead allocation per dimension, without double counting
--
-- Requires: 0001-0040 applied.
--
-- THE LIMITATION THIS REMOVES
--   0023 gave the business ONE overhead basis: a single quantity and unit for
--   the whole business. That was a real advance -- overhead per unit of
--   declared output rather than per ambiguous "serving" -- but a business
--   producing in more than one dimension could configure only one of them.
--   A litre basis blocked every gram-yield recipe, so a kitchen selling soup
--   AND bread could not cost both. Proven in tests/029 check 35.
--
-- THE ARCHITECTURE CHOSEN, AND WHY
--   Each OVERHEAD ITEM may declare its own basis; items that do not declare
--   one inherit the business default. Two nullable columns on a table that
--   already exists. No new table, no data migration, and every existing
--   configuration keeps its exact present behaviour because every item
--   inherits the single business basis it already had.
--
--   Items sharing a basis unit already behave as a pool, so a pool needs no
--   table of its own.
--
-- WHY NOT THE ALTERNATIVES
--   A separate overhead_pools table: a pool is (name, amounts, basis), and
--     overhead_items is already a per-business list of named amounts. A pool
--     table adds a second place to enforce RLS and forces existing items into
--     a synthetic default pool for no behavioural gain. Premature.
--   Recipe- or category-level allocation profiles: needs a mapping table plus
--     a join, and the mapping restates the dimension the recipe's yield unit
--     already carries. Storing a derivable fact twice invites drift -- the
--     defect 0040 had just corrected.
--   Nothing existing: the schema has no pool, profile or allocation structure.
--
-- DOUBLE COUNTING IS PREVENTED BY CONSTRUCTION
--   Every naira lives in exactly one overhead item, and every item allocates
--   through exactly one basis. There is no path by which one item allocates
--   through two bases, so no configuration can allocate the same money twice.
--   A business wanting N600,000 spread over both litres and kilograms must
--   SPLIT it into items that sum to N600,000; it cannot apply N600,000 to
--   each. The reconciliation invariant -- sum of item costs equals configured
--   overhead -- therefore holds by the shape of the data, not by a check.
--
-- WHAT BLOCKS, AND WHAT IS SCOPE
--   no effective basis at all            -> missing_overhead_basis   BLOCK
--   an item with no monthly cost         -> missing_overhead_config  BLOCK
--   an item INHERITING the business basis
--     into an incompatible dimension     -> overhead_basis_incompatible BLOCK
--   an item with its OWN basis in another
--     dimension                          -> not allocated to this recipe
--
--   The last case is not a silent omission: the business declared that this
--   item is allocated per litre, so a gram-yield recipe is outside its scope
--   by explicit configuration, and fn_overhead_breakdown states it item by
--   item. Where the business has NOT decided -- an item inheriting a default
--   that does not fit -- the engine still refuses rather than guessing.
-- ============================================================================

do $$
begin
  if exists (select 1 from information_schema.columns
              where table_name = 'overhead_items' and column_name = 'basis_qty') then
    raise exception '0041 preflight FAILED: overhead_items.basis_qty already exists.';
  end if;
  if not exists (select 1 from pg_proc where proname = 'fn_overhead_rate') then
    raise exception '0041 preflight FAILED: fn_overhead_rate is missing.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0041 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

alter table overhead_items
  add column basis_qty     numeric(14,3),
  add column basis_unit_id uuid references units(id);

alter table overhead_items
  add constraint chk_overhead_item_basis_pair
  check ((basis_qty is null) = (basis_unit_id is null));

alter table overhead_items
  add constraint chk_overhead_item_basis_positive
  check (basis_qty is null or basis_qty > 0);

comment on column overhead_items.basis_qty is
  'How much output this item is spread across. NULL inherits the business '
  'default from business_settings. Never a rate, always a quantity.';
comment on column overhead_items.basis_unit_id is
  'The unit of basis_qty. Paired with basis_qty by constraint.';

-- ----------------------------------------------------------------------------
-- PROVENANCE. One row per active overhead item, saying exactly what it
-- contributes to a recipe measured in p_target_unit_id and why.
-- ----------------------------------------------------------------------------
create or replace function fn_overhead_breakdown(
  p_business_id uuid,
  p_target_unit_id uuid)
returns table (
  item_id       uuid,
  item_name     text,
  monthly_cost  numeric,
  basis_qty     numeric,
  basis_unit    text,
  basis_source  text,     -- 'item' | 'business'
  basis_in_target numeric,
  rate          numeric,
  applies       boolean,
  reason        text)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare v_account_id uuid; v_def_qty numeric; v_def_unit uuid;
begin
  select account_id, overhead_basis_qty, overhead_basis_unit_id
    into v_account_id, v_def_qty, v_def_unit
  from business_settings where business_id = p_business_id;
  if v_account_id is null then return; end if;

  perform fn_require_cost_access(v_account_id);   -- AUTHORIZATION

  return query
  select oi.id,
         oi.name,
         oi.monthly_cost,
         coalesce(oi.basis_qty, v_def_qty),
         u.code,
         case when oi.basis_qty is not null then 'item' else 'business' end,
         b.converted,
         case when oi.monthly_cost is not null and b.converted > 0
              then oi.monthly_cost / b.converted end,
         (oi.monthly_cost is not null and b.converted > 0),
         case
           when oi.monthly_cost is null                      then 'no monthly cost recorded'
           when coalesce(oi.basis_qty, v_def_qty) is null    then 'no basis declared'
           when b.converted is null and oi.basis_qty is not null
                then 'allocated in another measurement, so not applied here'
           when b.converted is null                          then 'business basis cannot be expressed in this unit'
           else null
         end
    from overhead_items oi
    left join units u
      on u.id = coalesce(oi.basis_unit_id, v_def_unit)
    cross join lateral (
      select fn_convert_between_units(
               coalesce(oi.basis_qty, v_def_qty),
               coalesce(oi.basis_unit_id, v_def_unit),
               p_target_unit_id) as converted
    ) b
   where oi.business_id = p_business_id
     and oi.is_active
   order by oi.name;
end;
$$;

comment on function fn_overhead_breakdown(uuid, uuid) is
  'Item-by-item provenance: which overhead contributed, on what basis, at what '
  'rate, and where it did not apply and why.';

-- ----------------------------------------------------------------------------
-- WHY OVERHEAD CANNOT BE COSTED, or NULL if it can.
-- ----------------------------------------------------------------------------
create or replace function fn_overhead_problem(
  p_business_id uuid,
  p_target_unit_id uuid)
returns text
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare v_account_id uuid; v_enabled boolean; r record; v_any boolean := false;
begin
  select account_id, overhead_enabled into v_account_id, v_enabled
  from business_settings where business_id = p_business_id;
  if v_account_id is null then return null; end if;
  if not coalesce(v_enabled, false) then return null; end if;

  perform fn_require_cost_access(v_account_id);

  for r in select * from fn_overhead_breakdown(p_business_id, p_target_unit_id) loop
    v_any := true;
    if r.monthly_cost is null then return 'missing_overhead_config'; end if;
    if r.basis_qty is null    then return 'missing_overhead_basis';  end if;
    -- An item INHERITING the business basis into a dimension it cannot express
    -- means the business has not decided. Refuse rather than guess.
    if r.basis_in_target is null and r.basis_source = 'business' then
      return 'overhead_basis_incompatible';
    end if;
  end loop;

  -- Enabled with no active items at all is a declaration of zero overhead,
  -- not an unknown: there is nothing to allocate.
  return null;
end;
$$;

-- ----------------------------------------------------------------------------
-- THE RATE: the sum of each item's own rate. An item scoped to another
-- dimension contributes nothing here, which is the business's configuration.
-- ----------------------------------------------------------------------------
create or replace function fn_overhead_rate(
  p_business_id uuid,
  p_target_unit_id uuid)
returns numeric
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare v_rate numeric;
begin
  if p_business_id is null or p_target_unit_id is null then return null; end if;
  if fn_overhead_problem(p_business_id, p_target_unit_id) is not null then
    return null;                      -- blocked: never a zero
  end if;

  select coalesce(sum(rate) filter (where applies), 0)
    into v_rate
  from fn_overhead_breakdown(p_business_id, p_target_unit_id);

  return v_rate;
end;
$$;

CREATE OR REPLACE FUNCTION public.fn_compute_recipe_cost_snapshot(p_recipe_id uuid, p_as_of date DEFAULT CURRENT_DATE, p_created_by uuid DEFAULT auth.uid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r recipes%rowtype; bs business_settings%rowtype; core recipe_cost_result;
  v_overhead numeric := 0; v_oh_total numeric; v_oh_rate numeric;
  v_sold_by_format boolean;
  v_required integer; v_priced integer; v_unpriced jsonb; v_complete boolean;
  v_floor_pp numeric; v_snapshot uuid;
begin
  select * into r from recipes where id = p_recipe_id and deleted_at is null;
  if not found then raise exception 'Recipe % not found', p_recipe_id; end if;

  perform fn_require_cost_access(r.account_id);   -- AUTHORIZATION

  select * into bs from business_settings where business_id = r.business_id;
  if not found then
    raise exception 'Business settings missing for business %', r.business_id;
  end if;

  core := fn__recipe_cost_core(p_recipe_id, p_as_of, 0);

  v_required := core.required_inputs;
  v_priced   := core.priced_inputs;
  v_unpriced := core.unpriced_items;
  v_complete := core.is_complete;

  -- MODEL 1 vs MODEL 2 (owner decision, Phase 4 escalation).
  -- A recipe sold through its own business-defined formats does not need a
  -- portion size: the FORMAT is the commercial unit, and fn_variant_cost
  -- allocates the batch economics to each format. A recipe with no active
  -- sellable format is portion-based and still requires one. This is not
  -- "portion is optional" -- exactly one basis applies, and which one is
  -- determined here rather than guessed.
  select exists (
    select 1
      from recipe_variants rv
      join serving_formats sf on sf.id = rv.format_id
     where rv.recipe_id = p_recipe_id
       and rv.is_active
       and sf.is_active
  ) into v_sold_by_format;

  if bs.overhead_enabled then
    v_required := v_required + 1;

    -- 0041: the reason now comes from fn_overhead_problem, which reads each
    -- overhead item's OWN basis and falls back to the business default. The
    -- decision is made once, in one place, rather than re-derived here.
    declare v_oh_problem text;
    begin
      v_oh_problem := fn_overhead_problem(r.business_id, r.yield_unit_id);
      if v_oh_problem is not null then
        v_complete := false;
        v_unpriced := v_unpriced || jsonb_build_object(
          'recipe_id', p_recipe_id, 'business_id', r.business_id,
          'problem', v_oh_problem);
        v_overhead := null;
      else
        v_oh_rate := fn_overhead_rate(r.business_id, r.yield_unit_id);
        if r.portion_qty is null then
          -- No portion size. For a FORMAT-BASED recipe that is correct:
          -- overhead is allocated per format by fn_variant_cost as
          -- overhead_rate x resolved_qty, so there is no per-portion figure
          -- to compute and none is invented.
          v_overhead := null;
          if v_sold_by_format then
            v_priced := v_priced + 1;
          end if;
        else
          v_overhead := v_oh_rate * r.portion_qty;
          v_priced   := v_priced + 1;
        end if;
      end if;
    end;
  end if;

  if r.kind = 'dish' and not v_sold_by_format then
    -- MODEL 1, portion-based: the portion is the commercial unit, so its size
    -- is a required input.
    v_required := v_required + 1;
    if r.portion_qty is null then
      v_complete := false;
      v_unpriced := v_unpriced || jsonb_build_object(
        'recipe_id', p_recipe_id, 'problem', 'missing_portion_size');
    else
      v_priced := v_priced + 1;
    end if;
  end if;
  -- MODEL 2, format-based: no portion input is required and none is invented.
  -- Whether each format can actually be costed is decided per format by
  -- fn_variant_problem, which blocks on incompatible dimensions, missing
  -- conversions and unpriced packaging. A recipe can therefore be complete
  -- while one of its formats is not, which is the truth of the situation.

  if core.priced_inputs = 0 then
    v_floor_pp := null;
  elsif core.cost_per_yield_unit is not null and r.portion_qty is not null then
    v_floor_pp := core.cost_per_yield_unit * r.portion_qty + coalesce(v_overhead, 0);
  else
    v_floor_pp := null;
  end if;

  if jsonb_array_length(v_unpriced) > 0 then
    v_complete := false;
  end if;

  insert into cost_snapshots (
    account_id, business_id, recipe_id, computed_at,
    costing_method, wavg_window_days,
    is_complete, required_inputs, priced_inputs, excluded_inputs, unpriced_items,
    ingredient_cost, packaging_cost, labour_cost, overhead_cost,
    batch_cost, cost_per_yield_unit, cost_per_portion,
    floor_batch_cost, floor_cost_per_yield_unit, floor_cost_per_portion,
    created_by)
  values (
    r.account_id, r.business_id, p_recipe_id, now(),
    bs.costing_method, bs.wavg_window_days,
    v_complete, v_required, v_priced, core.excluded_inputs, v_unpriced,
    core.ingredient_cost, core.packaging_cost, core.labour_cost, v_overhead,
    case when v_complete then core.batch_cost end,
    case when v_complete then core.cost_per_yield_unit end,
    case when v_complete then v_floor_pp end,
    case when core.priced_inputs > 0 then core.batch_cost end,
    case when core.priced_inputs > 0 then core.cost_per_yield_unit end,
    v_floor_pp,
    p_created_by)
  returning id into v_snapshot;

  return v_snapshot;
end;
$function$;

do $$
declare v_pol int;
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'overhead_items' and column_name = 'basis_unit_id') then
    raise exception '0041 self-check FAILED: the per-item basis was not added.';
  end if;
  if not exists (select 1 from pg_proc where proname = 'fn_overhead_breakdown') then
    raise exception '0041 self-check FAILED: fn_overhead_breakdown is missing.';
  end if;
  if not exists (select 1 from pg_constraint where conname = 'chk_overhead_item_basis_pair') then
    raise exception '0041 self-check FAILED: the basis pair constraint is missing.';
  end if;
  if pg_get_functiondef((select oid from pg_proc where proname='fn_compute_recipe_cost_snapshot' and prokind='f'))
     !~ 'fn_overhead_problem' then
    raise exception '0041 self-check FAILED: the engine does not use fn_overhead_problem.';
  end if;
  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0041 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0041 OK: per-item overhead basis live, provenance exposed, 116 policies unchanged.';
end
$$;

-- ===================== 0042_dashboard_views.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0042: the dashboard's questions, answered in PostgreSQL
--
-- Requires: 0001-0041 applied.
--
-- WHY
--   The dashboard must answer five questions: what does this really cost me,
--   what should I charge, what am I making, which products make or lose money,
--   and is anything incomplete or out of date. Every one of those is a
--   financial judgement, so every one is answered here rather than assembled
--   in the browser.
--
--   v_onboarding_status already counts the early setup steps and is extended
--   rather than replaced. Two new views answer the questions it does not.
--
-- NO NEW TABLES. Nothing is stored; these are projections of what the costing
-- engine already knows.
-- ============================================================================

do $$
begin
  if exists (select 1 from pg_views where viewname = 'v_product_attention') then
    raise exception '0042 preflight FAILED: v_product_attention already exists.';
  end if;
  if not exists (select 1 from pg_views where viewname = 'v_recipe_basis') then
    raise exception '0042 preflight FAILED: 0039 must be applied first.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0042 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

-- ----------------------------------------------------------------------------
-- WHICH PRODUCTS NEED ATTENTION, and why -- in states a shopkeeper recognises.
--
-- One row per sellable thing: a recipe sold by the portion, or a recipe/format
-- pair. The state is decided here so the page cannot invent a different one.
-- ----------------------------------------------------------------------------
create view v_product_attention with (security_invoker = on) as
select
  pc.account_id,
  pc.business_id,
  pc.recipe_id,
  pc.variant_id,
  pc.name                                        as product_name,
  pc.format_name,
  pc.is_complete,
  pc.cost_per_portion                            as true_cost,
  pc.selling_price,
  pc.profit,
  pc.margin_pct,
  pc.markup_pct,
  pc.recommended_price,
  pc.target_margin,
  case
    when not pc.is_complete                    then 'costing_incomplete'
    when pc.selling_price is null              then 'no_price_yet'
    when pc.profit < 0                         then 'losing_money'
    when pc.margin_pct < pc.target_margin      then 'below_target'
    else                                            'healthy'
  end                                            as state,
  -- Ordering for a "needs attention" list: money being lost first, then
  -- margins under target, then things not yet finished, then the healthy ones.
  case
    when pc.is_complete and pc.profit < 0                       then 1
    when pc.is_complete and pc.margin_pct < pc.target_margin    then 2
    when pc.is_complete and pc.selling_price is null            then 3
    when not pc.is_complete                                     then 4
    else                                                             5
  end                                            as attention_rank
from v_price_check pc;

comment on view v_product_attention is
  'One row per sellable product with the state a business owner acts on: '
  'losing money, below target, no price yet, costing incomplete, or healthy.';

grant select on v_product_attention to authenticated;

-- ----------------------------------------------------------------------------
-- WHICH INGREDIENTS NEED A PRICE, or a newer one.
--
-- "Out of date" is not an opinion: it is a purchase older than the business's
-- own costing window, which is the same window the engine averages over. An
-- ingredient priced only by estimate is reported separately from one with no
-- price at all, because they need different actions.
-- ----------------------------------------------------------------------------
create view v_ingredient_price_status with (security_invoker = on) as
select
  i.account_id,
  b.id                                           as business_id,
  i.id                                           as ingredient_id,
  i.name                                         as ingredient_name,
  i.kind                                         as item_kind,
  latest.effective_date                          as last_purchase_date,
  latest.source                                  as last_source,
  bs.wavg_window_days,
  case
    when latest.effective_date is null                     then 'never_priced'
    when latest.source <> 'purchase'                       then 'estimate_only'
    when latest.effective_date
         < current_date - (bs.wavg_window_days || ' days')::interval
                                                           then 'out_of_date'
    else                                                        'current'
  end                                            as price_state,
  (select count(*) from recipe_lines rl
    where rl.ingredient_id = i.id and rl.is_cost_bearing)::int as used_in_recipes
from ingredients i
join businesses b        on b.account_id = i.account_id and b.deleted_at is null
join business_settings bs on bs.business_id = b.id
left join lateral (
  select ip.effective_date, ip.source
    from ingredient_prices ip
   where ip.ingredient_id = i.id
     and ip.account_id    = i.account_id
     and ip.reversed_at is null
     and ip.effective_date <= current_date
   order by ip.effective_date desc, ip.created_at desc
   limit 1
) latest on true
where i.deleted_at is null
  and i.is_active;

comment on view v_ingredient_price_status is
  'Whether each ingredient has a current purchase price, only an estimate, a '
  'price older than the business costing window, or none at all.';

grant select on v_ingredient_price_status to authenticated;

-- ----------------------------------------------------------------------------
-- The setup journey, extended with the steps 0039-0041 made possible.
-- Existing columns keep their names, types and positions; new ones are added
-- at the end. security_invoker is RESTATED -- a replaced view silently loses
-- it, which opened a cross-tenant read in Phase 3.
-- ----------------------------------------------------------------------------
create or replace view v_onboarding_status with (security_invoker = on) as
select b.account_id,
  b.id as business_id,
  b.name,
  (select count(*) from ingredients i
    where i.account_id = b.account_id and i.deleted_at is null) as ingredients,
  (select count(*) from ingredient_prices ip
    where ip.account_id = b.account_id and ip.reversed_at is null) as prices_entered,
  (select count(*) from recipes r
    where r.business_id = b.id and r.deleted_at is null) as recipes,
  (select count(*) from cost_snapshots s
    where s.business_id = b.id and s.is_complete) as complete_costings,
  (select count(*) from v_missing_unit_conversions m
    where m.account_id = b.account_id and m.reason <> 'suggested'::text) as blocking_conversions,
  (select count(*) from recipe_prices rp
     join recipes r2 on r2.id = rp.recipe_id
    where r2.business_id = b.id) as selling_prices_set,
  -- added by 0042
  (select count(*) from recipes r
    where r.business_id = b.id and r.deleted_at is null
      and r.batch_yield_qty is not null) as recipes_with_yield,
  (select count(*) from serving_formats sf
    where sf.business_id = b.id and sf.is_active) as serving_formats,
  (select count(*) from serving_format_packaging spk
    where spk.business_id = b.id) as packaging_lines,
  (select count(*) from labour_rates lr
    where lr.business_id = b.id and lr.is_active) as labour_rates,
  (select count(*) from overhead_items oi
    where oi.business_id = b.id and oi.is_active) as overhead_items,
  (select count(*) from v_product_attention pa
    where pa.business_id = b.id and pa.state = 'healthy') as products_ready
from businesses b
where b.deleted_at is null;

grant select on v_onboarding_status to authenticated;

do $$
declare v_pol int; v_unsafe text;
begin
  select string_agg(c.relname, ', ') into v_unsafe
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'v'
     and c.relname in ('v_product_attention','v_ingredient_price_status','v_onboarding_status')
     and not coalesce('security_invoker=on' = any(c.reloptions), false);
  if v_unsafe is not null then
    raise exception '0042 self-check FAILED: % lost security_invoker.', v_unsafe;
  end if;

  if (select count(*) from information_schema.columns
       where table_name = 'v_onboarding_status') <> 15 then
    raise exception '0042 self-check FAILED: v_onboarding_status has % columns, expected 15.',
      (select count(*) from information_schema.columns where table_name = 'v_onboarding_status');
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0042 self-check FAILED: policy count moved to %.', v_pol;
  end if;

  raise notice '0042 OK: dashboard views created, onboarding extended to 15 columns, 116 policies unchanged.';
end
$$;

-- ===================== 0043_customer_and_line_scope.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0043: customer detail, and tenant scope on order lines
--
-- Requires: 0001-0042 applied.
--
-- Two small additions, no behaviour change.
--
--   customers.notes / .company  -- what a caterer needs to remember about a
--     client. Deliberately nothing more: no address, no birthday, no marketing
--     consent. Data not collected cannot be leaked.
--
--   order_lines.business_id  -- every other tenant table carries it. Without
--     it, every sales query must join orders to scope by business, and a
--     reporting view can silently lose that join. Backfilled from the parent
--     order, then made NOT NULL, with the composite foreign key the rest of
--     the schema uses so a line can never point at another account's order.
--
--     A denormalised column is only safe while it cannot disagree with the
--     row it was copied from, so it is not the caller's to set. A trigger
--     derives it from the parent order on every insert and update, and
--     refuses a value that contradicts that order. Callers that already
--     insert order lines keep working unchanged; callers that try to place
--     a line in another business are stopped.
-- ============================================================================

do $$
begin
  if exists (select 1 from information_schema.columns
              where table_name = 'order_lines' and column_name = 'business_id') then
    raise exception '0043 preflight FAILED: order_lines.business_id already exists.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0043 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

alter table customers
  add column notes   text,
  add column company text;

comment on column customers.company is
  'The organisation a customer orders for, when that differs from their name.';

alter table order_lines add column business_id uuid;

update order_lines ol
   set business_id = o.business_id
  from orders o
 where o.id = ol.order_id
   and ol.business_id is null;

do $$
declare v_orphan int;
begin
  select count(*) into v_orphan from order_lines where business_id is null;
  if v_orphan > 0 then
    raise exception '0043 FAILED: % order line(s) have no business after backfill. '
                    'Refusing to add NOT NULL over unresolved rows.', v_orphan;
  end if;
end
$$;

alter table order_lines alter column business_id set not null;

alter table order_lines
  add constraint fk_order_lines_business_id_account
  foreign key (business_id, account_id) references businesses(id, account_id);

-- The line always belongs to whatever business the order belongs to. Derived,
-- never supplied. A caller that supplies a different one is making a mistake
-- that would put revenue under the wrong business, so it is refused loudly
-- rather than silently overwritten.
create or replace function fn_order_line_scope()
returns trigger
language plpgsql
as $fn$
declare v_business uuid;
begin
  select o.business_id into v_business from orders o where o.id = new.order_id;
  if v_business is null then
    raise exception 'Order % not found; cannot scope this line.', new.order_id
      using errcode = 'foreign_key_violation';
  end if;

  if new.business_id is not null and new.business_id <> v_business then
    raise exception
      'This line belongs to an order in a different business. Add it to that order instead.'
      using errcode = 'check_violation';
  end if;

  new.business_id := v_business;
  return new;
end
$fn$;

-- Fires before the tenant foreign key is checked, and before the revenue and
-- freeze guards care about it, so an ordinary insert never has to name it.
create trigger trg_order_lines_scope
  before insert or update on order_lines
  for each row execute function fn_order_line_scope();

do $$
declare v_pol int;
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'order_lines' and column_name = 'business_id'
                    and is_nullable = 'NO') then
    raise exception '0043 self-check FAILED: business_id is missing or nullable.';
  end if;
  if not exists (select 1 from pg_constraint
                  where conname = 'fk_order_lines_business_id_account') then
    raise exception '0043 self-check FAILED: the tenant foreign key is missing.';
  end if;
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'order_lines' and t.tgname = 'trg_order_lines_scope') then
    raise exception '0043 self-check FAILED: the scope trigger is missing.';
  end if;
  if exists (select 1 from order_lines ol join orders o on o.id = ol.order_id
              where ol.business_id <> o.business_id) then
    raise exception '0043 self-check FAILED: a line disagrees with its order.';
  end if;
  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0043 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0043 OK: customer detail added, order lines scoped and derived, 116 policies unchanged.';
end
$$;

-- ===================== 0044_discounts.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0044: discounts, and the deterministic allocation of an order discount
--
-- Requires: 0001-0043 applied.
--
-- A caterer discounts in two ways, and they mean different things:
--
--   a line discount   -- "the jollof is 200 naira off a plate for this order"
--   an order discount -- "take 5,000 naira off the whole thing"
--
-- Both are recorded as naira amounts, never percentages. A percentage has to
-- be turned into naira eventually, and whoever does that rounding owns the
-- argument about the missing kobo. An amount is simply what the owner gave
-- away.
--
-- The line discount is stored, because the owner decided it per line.
-- The order discount is stored once, on the order, and *allocated* to lines
-- pro rata by line revenue so that per-product margin means something. The
-- allocation is derived, never stored, for two reasons:
--
--   it cannot drift from the numbers it is derived from, and
--   its inputs are already immutable once the sale is confirmed, so the
--   allocation is immutable too, without a second thing to freeze.
--
-- Gross revenue, the line discount, the allocated order discount and net
-- revenue are all reported separately. A discount is a decision worth seeing,
-- not something to bury inside a reduced price.
-- ============================================================================

do $$
begin
  if exists (select 1 from information_schema.columns
              where table_name = 'order_lines' and column_name = 'discount_amount') then
    raise exception '0044 preflight FAILED: order_lines.discount_amount already exists.';
  end if;
  if exists (select 1 from information_schema.columns
              where table_name = 'orders' and column_name = 'order_discount') then
    raise exception '0044 preflight FAILED: orders.order_discount already exists.';
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'order_lines' and column_name = 'business_id') then
    raise exception '0044 preflight FAILED: 0043 has not been applied.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0044 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- 1. The two columns
-- ---------------------------------------------------------------------------

alter table order_lines
  add column discount_amount numeric(14,2) not null default 0;

-- Gross revenue is qty * unit_price. Giving away more than the line is worth
-- is not a discount, it is a refund, and Menu Master does not model refunds.
alter table order_lines
  add constraint order_lines_discount_amount_check
  check (discount_amount >= 0 and discount_amount <= qty * unit_price);

comment on column order_lines.discount_amount is
  'Naira taken off this line specifically. Never a percentage.';

alter table orders
  add column order_discount numeric(14,2) not null default 0;

alter table orders
  add constraint orders_order_discount_check check (order_discount >= 0);

comment on column orders.order_discount is
  'Naira taken off the order as a whole, allocated across its lines pro rata '
  'by line revenue. See fn_allocate_order_discount.';

-- ---------------------------------------------------------------------------
-- 2. An order discount cannot exceed what the order is worth
--
-- This one cannot be a CHECK: it spans rows in another table. It is enforced
-- where the owner sets the discount, and again, harder, at confirmation.
--
-- Deliberately NOT enforced when a line is removed. Removing a line from a
-- draft can leave the discount larger than what remains; refusing the delete
-- would trap the owner between two edits they are allowed to make. The draft
-- is simply invalid until they lower the discount, and confirmation says so.
-- ---------------------------------------------------------------------------

create or replace function fn_guard_order_discount()
returns trigger
language plpgsql
as $fn$
declare v_subtotal numeric(14,2);
begin
  if tg_op = 'UPDATE' and new.order_discount is not distinct from old.order_discount then
    return new;
  end if;
  if new.order_discount = 0 then
    return new;
  end if;

  select coalesce(sum(ol.qty * ol.unit_price - ol.discount_amount), 0)
    into v_subtotal
    from order_lines ol
   where ol.order_id = new.id;

  -- No lines yet: the owner is filling in the order header first. Confirmation
  -- is the backstop, and an order with no lines cannot be confirmed at all.
  if not exists (select 1 from order_lines where order_id = new.id) then
    return new;
  end if;

  if new.order_discount > v_subtotal then
    raise exception
      'The order discount of % is more than the order is worth (%). Lower the discount.',
      to_char(new.order_discount, 'FM999999990.00'),
      to_char(v_subtotal, 'FM999999990.00')
      using errcode = 'check_violation';
  end if;

  return new;
end
$fn$;

create trigger trg_orders_discount
  before insert or update on orders
  for each row execute function fn_guard_order_discount();

-- ---------------------------------------------------------------------------
-- 3. The allocation
--
--   line revenue  = qty * unit_price - line discount
--   share_i       = round(order_discount * line_revenue_i / subtotal, 2)
--
-- Rounding each share independently leaves a residual of a few kobo either
-- way. That residual goes to the single largest line by revenue, ties broken
-- by line id, so the sum of the allocations equals the order discount exactly,
-- always, and the same order always allocates the same way.
--
-- The function never raises. It is read by reporting views, and a view that
-- throws on one bad draft shows nothing for anybody. A draft whose discount
-- exceeds its own revenue allocates more than a line is worth and reports a
-- negative net revenue -- which is the truth about that draft. Confirmation
-- refuses it.
--
-- Called with no argument it allocates across every order the caller can see,
-- in one pass, which is how the sales views use it. Row level security applies
-- normally: this function is not SECURITY DEFINER and holds no privilege of
-- its own.
-- ---------------------------------------------------------------------------

create or replace function fn_allocate_order_discount(p_order_id uuid default null)
returns table (
  order_line_id            uuid,
  order_id                 uuid,
  gross_revenue            numeric(14,2),
  line_discount            numeric(14,2),
  line_revenue             numeric(14,2),
  allocated_order_discount numeric(14,2),
  net_revenue              numeric(14,2)
)
language sql
stable
as $fn$
  with l as (
    select ol.id,
           ol.order_id                                              as ord,
           (ol.qty * ol.unit_price)::numeric(14,2)                  as gross,
           ol.discount_amount,
           (ol.qty * ol.unit_price - ol.discount_amount)::numeric(14,2) as revenue,
           o.order_discount
      from order_lines ol
      join orders o on o.id = ol.order_id
     where p_order_id is null or ol.order_id = p_order_id
  ),
  ranked as (
    select l.*,
           sum(l.revenue) over (partition by l.ord)                 as subtotal,
           row_number() over (partition by l.ord
                              order by l.revenue desc, l.id)        as rn
      from l
  ),
  shared as (
    select ranked.*,
           case
             when ranked.order_discount = 0 then 0::numeric(14,2)
             when ranked.subtotal > 0
               then round(ranked.order_discount * ranked.revenue / ranked.subtotal, 2)
             -- Nothing to allocate against. The whole discount lands on the
             -- first line rather than quietly evaporating.
             else 0::numeric(14,2)
           end as share
      from ranked
  ),
  residual as (
    select shared.*,
           sum(shared.share) over (partition by shared.ord) as share_total
      from shared
  )
  select residual.id,
         residual.ord,
         residual.gross,
         residual.discount_amount,
         residual.revenue,
         (residual.share
            + case when residual.rn = 1
                   then residual.order_discount - residual.share_total
                   else 0 end)::numeric(14,2),
         (residual.revenue
            - (residual.share
                 + case when residual.rn = 1
                        then residual.order_discount - residual.share_total
                        else 0 end))::numeric(14,2)
    from residual;
$fn$;

comment on function fn_allocate_order_discount(uuid) is
  'Splits orders.order_discount across an order''s lines pro rata by line '
  'revenue. The kobo residual goes to the largest line, so the allocations '
  'sum to the order discount exactly. Pass null to allocate every visible order.';

grant execute on function fn_allocate_order_discount(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Discounts are revenue, so a confirmed sale must not be able to move them
--
-- Both guards already exist and already freeze everything that determines
-- revenue. They simply did not know about discounts yet. Extended, not
-- replaced.
-- ---------------------------------------------------------------------------

create or replace function fn_guard_order_line_revenue()
returns trigger
language plpgsql
as $fn$
declare v_final timestamptz; v_void timestamptz; v_order uuid;
begin
  v_order := coalesce(new.order_id, old.order_id);
  select finalised_at, voided_at into v_final, v_void from orders where id = v_order;

  if v_final is null then
    return coalesce(new, old);            -- still a draft: freely editable
  end if;

  if tg_op = 'INSERT' then
    raise exception 'Order % is finalised. No further lines may be added.', v_order
      using errcode='check_violation';
  elsif tg_op = 'DELETE' then
    raise exception 'Order % is finalised. Lines cannot be deleted. Void the order instead.', v_order
      using errcode='check_violation';
  else
    -- discount_amount joins the tuple: a discount changes revenue, and revenue
    -- on a confirmed sale is history.
    if (old.qty, old.unit_price, old.recipe_id, old.discount_amount)
       is distinct from (new.qty, new.unit_price, new.recipe_id, new.discount_amount) then
      raise exception 'Revenue on a finalised sale is immutable. Void and reissue instead.'
        using errcode='check_violation';
    end if;
  end if;

  return coalesce(new, old);
end;
$fn$;

create or replace function fn_guard_finalised_order()
returns trigger
language plpgsql
as $fn$
begin
  if tg_op = 'DELETE' then
    if old.finalised_at is not null then
      raise exception 'Order % is finalised and cannot be deleted. Void it instead.', old.id
        using errcode='check_violation';
    end if;
    return old;
  end if;

  if old.voided_at is not null then
    raise exception 'Order % is voided. Its record is closed.', old.id
      using errcode='check_violation';
  end if;

  if old.finalised_at is not null then
    -- Settlement may still move after the sale: collecting payment later is not
    -- a revenue rewrite. Everything that determines revenue is frozen, and the
    -- order discount determines revenue.
    if (old.account_id, old.business_id, old.location_id, old.customer_id,
        old.channel_id, old.order_no, old.order_date, old.status,
        old.finalised_at, old.replaces, old.order_discount)
       is distinct from
       (new.account_id, new.business_id, new.location_id, new.customer_id,
        new.channel_id, new.order_no, new.order_date, new.status,
        new.finalised_at, new.replaces, new.order_discount)
    then
      raise exception 'Order % is finalised. Only payment state may change, or void it.', old.id
        using errcode='check_violation';
    end if;
  end if;

  return new;
end;
$fn$;

-- ---------------------------------------------------------------------------
-- 5. Self-check
-- ---------------------------------------------------------------------------

do $$
declare v_pol int;
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'order_lines' and column_name = 'discount_amount'
                    and is_nullable = 'NO' and column_default = '0') then
    raise exception '0044 self-check FAILED: order_lines.discount_amount is wrong or missing.';
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'orders' and column_name = 'order_discount'
                    and is_nullable = 'NO' and column_default = '0') then
    raise exception '0044 self-check FAILED: orders.order_discount is wrong or missing.';
  end if;
  if not exists (select 1 from pg_constraint where conname = 'order_lines_discount_amount_check') then
    raise exception '0044 self-check FAILED: the line discount ceiling is missing.';
  end if;
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'orders' and t.tgname = 'trg_orders_discount') then
    raise exception '0044 self-check FAILED: the order discount guard is missing.';
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'public' and p.proname = 'fn_allocate_order_discount') then
    raise exception '0044 self-check FAILED: fn_allocate_order_discount is missing.';
  end if;
  -- Every existing order still reconciles: nothing has a discount yet, so
  -- every allocation must be zero and every net must equal gross.
  if exists (select 1 from fn_allocate_order_discount()
              where allocated_order_discount <> 0 or net_revenue <> gross_revenue) then
    raise exception '0044 self-check FAILED: a pre-existing order changed value.';
  end if;
  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0044 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0044 OK: discounts added, allocation deterministic, 116 policies unchanged.';
end
$$;

-- ===================== 0045_confirmation_freeze.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0045: the freeze happens at confirmation, not at typing
--
-- Requires: 0001-0044 applied.
--
-- The problem this fixes
-- ---------------------
-- An order line froze its cost the instant it was typed. A caterer building a
-- Saturday order on Monday, adding to it on Tuesday and confirming it on
-- Wednesday ended up with three different days' economics inside one sale.
-- Worse, the Monday line froze a cost for a sale that had not happened and
-- might never happen.
--
-- The economics of a sale are the economics at the moment the sale is
-- committed. So the freeze moves to confirmation, and it freezes every line
-- together, from one instant, in one statement.
--
-- What that requires
-- ------------------
--   the BEFORE INSERT freeze on order_lines is removed; drafts stay live and
--     recost themselves as ingredient prices move, which is the point of a
--     draft
--
--   fn_guard_frozen_cost, which refused every change to a frozen cost, has to
--     permit exactly one: null -> value, performed by the confirmation itself.
--     It now recognises that operation rather than trusting any caller who
--     happens to be updating a draft line
--
--   orders.status defaulted to 'confirmed', so an order inserted without a
--     status was born committed and never made the transition that freezes it.
--     The default becomes 'draft'
--
--   status and finalised_at were independent, and every guard keyed on
--     finalised_at while status was decorative. Confirmation now sets both in
--     one statement, so there is one boundary rather than two
--
-- sales_entries is untouched. A quick sale has no draft state -- it is a
-- record of something that already happened -- so it still freezes on arrival.
-- The two paths now share one implementation of "what does this product cost
-- right now", so they cannot drift apart.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'order_lines' and t.tgname = 'trg_order_lines_freeze') then
    raise exception '0045 preflight FAILED: trg_order_lines_freeze is already gone.';
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'orders' and column_name = 'order_discount') then
    raise exception '0045 preflight FAILED: 0044 has not been applied.';
  end if;
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'sales_entries' and t.tgname = 'trg_sales_entries_freeze') then
    raise exception '0045 preflight FAILED: the sales_entries freeze is missing.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0045 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- 0. The orders the old default left behind
--
-- Until this migration, orders.status defaulted to 'confirmed' while
-- finalised_at was set only by fn_finalise_order. So an order inserted and
-- never explicitly finalised sat in a third state: counted as revenue by the
-- reporting views, which keyed on status, but not locked by the guards, which
-- key on finalised_at. Its lines were frozen at insert regardless.
--
-- Phase 6 merges those two tiers into one boundary. These rows have to land
-- somewhere, and there are only two honest choices:
--
--   drop them from revenue -- which silently changes the owner's historical
--     figures, the exact thing this phase exists to prevent; or
--   record when they were recognised -- which is what the old system meant by
--     'confirmed' from the moment of creation.
--
-- The second. finalised_at takes the order's own created_at and finalised_by
-- its created_by: not invented, read off the row. NO LINE IS TOUCHED, so no
-- historical sale is re-costed and every frozen figure stays exactly as it was.
--
-- Reported, never silent. Voided orders and drafts are left alone; both are
-- excluded from reporting before and after, so neither needs a decision.
-- ---------------------------------------------------------------------------

do $$
declare v_n int;
begin
  select count(*) into v_n from orders
   where status not in ('draft', 'cancelled')
     and finalised_at is null and voided_at is null;
  if v_n > 0 then
    raise notice '0045: % order(s) were recognised as sales under the old default '
                 'and carry no confirmation time. Recording their creation time as '
                 'their confirmation time so their revenue does not change.', v_n;
  else
    raise notice '0045: no legacy orders need reconciling.';
  end if;
end
$$;

update orders
   set finalised_at = created_at,
       finalised_by = created_by
 where status not in ('draft', 'cancelled')
   and finalised_at is null
   and voided_at is null;

-- ---------------------------------------------------------------------------
-- 1. One answer to "what does this product cost right now"
--
-- fn_freeze_sale_cost held this rule for quick sales. Confirmation needs the
-- identical rule for order lines. Rather than write it twice -- which is
-- exactly how the 0040 defect happened -- it moves into one function that both
-- callers use. The rule itself is unchanged, including the gate that an
-- incomplete cost is not a cost.
-- ---------------------------------------------------------------------------

do $$
begin
  if not exists (select 1 from pg_type where typname = 'frozen_sale_cost') then
    create type frozen_sale_cost as (
      cost_snapshot_id  uuid,
      unit_cost_at_sale numeric(18,4)
    );
  end if;
end
$$;

-- SECURITY DEFINER, so it must scope itself twice over: it refuses a caller
-- who is not a member of the account it is asked about, and it filters on that
-- account explicitly rather than inferring it from whatever snapshot it finds.
-- Without the first check a definer function taking an account id is simply a
-- cost-reading service for anybody who can guess one.
--
-- Membership, not cost access: a sales user may confirm an order, and the
-- freeze runs on their behalf, while they still cannot read a cost figure
-- anywhere in the product. That boundary is Gate 1's and does not move here.
create or replace function fn_frozen_sale_cost(
  p_account_id uuid,
  p_recipe_id  uuid,
  p_variant_id uuid
)
returns frozen_sale_cost
language plpgsql
stable
security definer
set search_path to 'public'
as $fn$
declare s cost_snapshots%rowtype; r frozen_sale_cost;
begin
  perform fn_require_member(p_account_id);

  r := row(null, null)::frozen_sale_cost;

  if p_recipe_id is null then
    return r;                       -- an ad hoc line has no product to cost
  end if;

  if p_variant_id is not null then
    -- what was actually sold is the variant, so that is what is frozen
    select * into s
      from cost_snapshots
     where account_id = p_account_id and variant_id = p_variant_id
     order by computed_at desc, seq desc
     limit 1;
  else
    select * into s
      from cost_snapshots
     where account_id = p_account_id
       and recipe_id = p_recipe_id and variant_id is null
     order by computed_at desc, seq desc
     limit 1;
  end if;

  -- The gate. An incomplete cost is not a cost, and a missing cost stays
  -- missing: it is never rounded down to zero.
  if not found or not s.is_complete or s.cost_per_portion is null then
    return r;
  end if;

  return row(s.id, s.cost_per_portion)::frozen_sale_cost;
end
$fn$;

comment on function fn_frozen_sale_cost(uuid, uuid, uuid) is
  'The cost to freeze against a sale of this product right now, or (null,null) '
  'when the product is not fully costed. Shared by quick sales and by order '
  'confirmation so the two cannot diverge.';

-- fn_freeze_sale_cost keeps its exact behaviour; only its body moves.
create or replace function fn_freeze_sale_cost()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $fn$
declare c frozen_sale_cost;
begin
  c := fn_frozen_sale_cost(new.account_id, new.recipe_id, new.variant_id);
  new.cost_snapshot_id  := c.cost_snapshot_id;
  new.unit_cost_at_sale := c.unit_cost_at_sale;
  return new;
end
$fn$;

-- ---------------------------------------------------------------------------
-- 2. Drafts stay live
-- ---------------------------------------------------------------------------

drop trigger if exists trg_order_lines_freeze on order_lines;

-- ---------------------------------------------------------------------------
-- 3. The frozen cost becomes writable exactly once, by exactly one operation
--
-- The old guard refused every change on UPDATE, which would have made the
-- confirmation freeze impossible. It now permits the single transition
-- null -> value, and only while fn_confirm_order is performing it. The marker
-- is set with SET LOCAL inside that function, so it dies with the transaction
-- and cannot be forged from a session that is not confirming this order.
--
-- Everything else is still refused: value -> different value, value -> null,
-- and null -> value written by anyone other than the confirmation.
--
-- The guard now also covers INSERT. Without the old BEFORE INSERT freeze,
-- nothing else would stop a caller inserting a draft line with a cost of its
-- own choosing.
-- ---------------------------------------------------------------------------

create or replace function fn_guard_frozen_cost()
returns trigger
language plpgsql
as $fn$
declare v_confirming text;
begin
  if tg_op = 'INSERT' then
    if new.cost_snapshot_id is not null or new.unit_cost_at_sale is not null then
      raise exception
        'A cost is frozen when the sale is confirmed, not when the line is added.'
        using errcode = 'check_violation';
    end if;
    return new;
  end if;

  if new.cost_snapshot_id  is not distinct from old.cost_snapshot_id
 and new.unit_cost_at_sale is not distinct from old.unit_cost_at_sale then
    return new;                          -- the frozen cost is not moving
  end if;

  v_confirming := current_setting('menumaster.confirming_order', true);

  if old.cost_snapshot_id is null
 and old.unit_cost_at_sale is null
 and v_confirming is not null
 and v_confirming <> ''
 and v_confirming = new.order_id::text then
    return new;                          -- the confirmation freeze: once, one way
  end if;

  raise exception
    'The cost frozen at sale time cannot be changed. Void the sale and reissue instead.'
    using errcode = 'check_violation';
end
$fn$;

drop trigger if exists trg_order_lines_frozen on order_lines;
create trigger trg_order_lines_frozen
  before insert or update on order_lines
  for each row execute function fn_guard_frozen_cost();

-- ---------------------------------------------------------------------------
-- 4. An order is born a draft
-- ---------------------------------------------------------------------------

alter table orders alter column status set default 'draft';

-- ---------------------------------------------------------------------------
-- 5. Confirmation
--
-- One transaction, one row lock, one UPDATE across every line. There is no
-- path to a half-frozen confirmed order: if anything raises, the whole
-- confirmation rolls back and the order is still a draft.
--
-- A line whose product is not fully costed freezes to NULL. That is a valid
-- outcome, not a failure -- the sale really did happen, and Menu Master will
-- not invent a cost for it. The function reports how many lines are in that
-- state so the caller can say so plainly.
-- ---------------------------------------------------------------------------

create or replace function fn_confirm_order(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $fn$
declare
  v_o        orders%rowtype;
  v_lines    integer;
  v_subtotal numeric(14,2);
  v_costed   integer;
begin
  select * into v_o from orders where id = p_order_id for update;
  if not found then raise exception 'Order % not found', p_order_id; end if;

  perform fn_require_account_role(v_o.account_id,
    array['owner','manager','sales']::member_role[], 'confirming orders');

  if v_o.voided_at is not null then
    raise exception 'Order % is voided and cannot be confirmed', p_order_id
      using errcode='check_violation';
  end if;
  if v_o.finalised_at is not null then
    raise exception 'Order % is already confirmed', p_order_id
      using errcode='check_violation';
  end if;

  select count(*), coalesce(sum(qty * unit_price - discount_amount), 0)
    into v_lines, v_subtotal
    from order_lines where order_id = p_order_id;

  if v_lines = 0 then
    raise exception 'Order % has no lines', p_order_id using errcode='check_violation';
  end if;

  -- The order-level check 0044 could not express as a CHECK constraint. A
  -- draft is allowed to be temporarily inconsistent; a confirmed sale is not.
  if v_o.order_discount > v_subtotal then
    raise exception
      'The order discount of % is more than the order is worth (%). Lower the discount before confirming.',
      to_char(v_o.order_discount, 'FM999999990.00'),
      to_char(v_subtotal, 'FM999999990.00')
      using errcode='check_violation';
  end if;

  -- Opens the one-way window in fn_guard_frozen_cost. SET LOCAL: it is gone at
  -- the end of this transaction whether it commits or rolls back.
  perform set_config('menumaster.confirming_order', p_order_id::text, true);

  -- Every line, one statement, one instant. now() is the transaction time, so
  -- every line freezes against the same moment by construction.
  --
  -- The lateral call lives in a subquery rather than the UPDATE's own FROM
  -- clause: an UPDATE's FROM cannot reference the row being updated.
  update order_lines ol
     set cost_snapshot_id  = f.cost_snapshot_id,
         unit_cost_at_sale = f.unit_cost_at_sale
    from (
      select l.id, c.cost_snapshot_id, c.unit_cost_at_sale
        from order_lines l
        cross join lateral fn_frozen_sale_cost(l.account_id, l.recipe_id, l.variant_id) c
       where l.order_id = p_order_id
    ) f
   where ol.id = f.id;

  perform set_config('menumaster.confirming_order', '', true);

  select count(*) into v_costed
    from order_lines where order_id = p_order_id and unit_cost_at_sale is not null;

  update orders
     set status       = 'confirmed',
         finalised_at = now(),
         finalised_by = auth.uid()
   where id = p_order_id;

  return jsonb_build_object(
    'confirmed',          true,
    'order_id',           p_order_id,
    'lines_frozen',       v_lines,
    'lines_without_cost', v_lines - v_costed);
end
$fn$;

comment on function fn_confirm_order(uuid) is
  'Commits a draft order: freezes every line''s cost from one instant and sets '
  'status and finalised_at together. The only way an order reaches confirmed.';

grant execute on function fn_confirm_order(uuid) to authenticated;

-- 0018 removed PUBLIC and anon from every fn_*. It was a sweep, not a standing
-- rule, so every function added since has quietly arrived executable by
-- everyone. Restated here for the two this migration adds; 0048 restores the
-- rule for the whole schema and tests/034 keeps it restored.
revoke all on function fn_confirm_order(uuid) from public, anon;
revoke all on function fn_frozen_sale_cost(uuid, uuid, uuid) from public, anon;
grant execute on function fn_frozen_sale_cost(uuid, uuid, uuid) to authenticated;

-- fn_finalise_order keeps working, and keeps its old return shape: callers
-- reading ->>'finalised' must not start getting NULL. It is the same operation
-- under an older name, so it delegates rather than holding a second copy of
-- the rules.
create or replace function fn_finalise_order(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $fn$
declare v jsonb;
begin
  v := fn_confirm_order(p_order_id);
  return jsonb_build_object(
    'finalised', true,
    'order_id',  p_order_id,
    'lines',     v->'lines_frozen');
end
$fn$;

comment on function fn_finalise_order(uuid) is
  'Superseded by fn_confirm_order, which it calls. Kept so existing callers '
  'do not break.';

-- ---------------------------------------------------------------------------
-- 6. An order cannot be talked into being confirmed
--
-- Every guard in the schema keys on finalised_at, and status was decorative.
-- With status now meaning something, an ordinary UPDATE could set it to
-- 'confirmed' while finalised_at stayed null -- an order that looks like a sale
-- to a reader and like a draft to every guard, with no frozen cost. An INSERT
-- could do the same in one step.
--
-- So status and finalised_at move together, and only fn_confirm_order moves
-- them. Cancelling is exempt: it is its own path and is not a confirmation.
--
-- Service context is exempt, deliberately. An operator repairing data through
-- the service role is not the 'normal application', and taking that away would
-- remove the only recovery route. It is recorded here rather than hidden.
-- ---------------------------------------------------------------------------

create or replace function fn_guard_order_lifecycle()
returns trigger
language plpgsql
as $fn$
begin
  if fn_is_service_context() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' or new.finalised_at is not null then
      raise exception
        'An order starts as a draft. Confirm it when the sale is agreed.'
        using errcode = 'check_violation';
    end if;
    return new;
  end if;

  if new.status is distinct from old.status
     and new.status <> 'cancelled'
     and old.finalised_at is null
     and new.finalised_at is null then
    raise exception
      'This order is still a draft. Confirm it to record the sale.'
      using errcode = 'check_violation';
  end if;

  if new.finalised_at is not null and new.status = 'draft' then
    raise exception 'A confirmed sale cannot also be a draft.'
      using errcode = 'check_violation';
  end if;

  return new;
end
$fn$;

revoke all on function fn_guard_order_lifecycle() from public, anon;

create trigger trg_orders_lifecycle
  before insert or update on orders
  for each row execute function fn_guard_order_lifecycle();

-- ---------------------------------------------------------------------------
-- 7. Self-check
-- ---------------------------------------------------------------------------

do $$
declare v_pol int;
begin
  if exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
              where c.relname = 'order_lines' and t.tgname = 'trg_order_lines_freeze') then
    raise exception '0045 self-check FAILED: the insert-time freeze survived.';
  end if;
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'sales_entries' and t.tgname = 'trg_sales_entries_freeze') then
    raise exception '0045 self-check FAILED: the sales_entries freeze was disturbed.';
  end if;
  if (select column_default from information_schema.columns
       where table_name = 'orders' and column_name = 'status')
     is distinct from '''draft''::order_status' then
    raise exception '0045 self-check FAILED: orders.status does not default to draft.';
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'public' and p.proname = 'fn_confirm_order') then
    raise exception '0045 self-check FAILED: fn_confirm_order is missing.';
  end if;
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'order_lines' and t.tgname = 'trg_order_lines_frozen'
                    and (t.tgtype & 4) = 4 and (t.tgtype & 16) = 16) then
    raise exception '0045 self-check FAILED: the frozen-cost guard does not cover insert and update.';
  end if;
  if not exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'orders' and t.tgname = 'trg_orders_lifecycle') then
    raise exception '0045 self-check FAILED: the lifecycle guard is missing.';
  end if;
  -- Every order that reads as a sale must carry a confirmation time. Anything
  -- left here would be counted by the old reporting and ignored by the new.
  if exists (select 1 from orders
              where status not in ('draft', 'cancelled')
                and finalised_at is null and voided_at is null) then
    raise exception '0045 self-check FAILED: % order(s) read as sales with no confirmation time.',
      (select count(*) from orders where status not in ('draft', 'cancelled')
        and finalised_at is null and voided_at is null);
  end if;
  -- A definer function that takes an account id and does not check it is a
  -- cost-reading service for anyone who can guess one.
  if pg_get_functiondef((select oid from pg_proc
                          where proname = 'fn_frozen_sale_cost'
                            and pronamespace = 'public'::regnamespace))
     !~ 'fn_require_member' then
    raise exception '0045 self-check FAILED: fn_frozen_sale_cost does not check membership.';
  end if;
  -- Nothing already confirmed may have been disturbed by any of this.
  if exists (select 1 from order_lines ol join orders o on o.id = ol.order_id
              where o.finalised_at is not null and ol.recipe_id is not null
                and ol.cost_snapshot_id is null and ol.unit_cost_at_sale is not null) then
    raise exception '0045 self-check FAILED: a confirmed line lost its snapshot.';
  end if;
  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0045 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0045 OK: freeze moved to confirmation, drafts live, 116 policies unchanged.';
end
$$;

-- ===================== 0046_cost_provenance.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0046: a frozen cost that can still be explained years later
--
-- Requires: 0001-0045 applied.
--
-- The frozen total was already immutable. The *explanation* of it was not.
--
-- Two things a snapshot needed and did not record:
--
--   B-1  a format-based variant's overhead share. The total included it, but
--        the breakdown had to reconstruct it by asking fn_overhead_rate about
--        TODAY's configuration. Change the overhead basis tomorrow and the
--        frozen total is still right while the breakdown quietly stops adding
--        up to it.
--
--   B-2  the portion size used at compute time. cost_per_portion is
--        cost_per_yield_unit x portion_qty, and portion_qty lives on recipes,
--        which is mutable. Change the portion size and 1.70/g x ? = 850 has
--        lost its "?".
--
-- Two nullable columns fix both. No child table: a breakdown table would be a
-- second place component figures live, needing its own RLS, its own
-- immutability trigger and its own reconciliation. The snapshot row is already
-- immutable and already holds every other component.
--
-- The more important half is the refactor. Rather than have the snapshot
-- writer recompute the components -- which is exactly how the 0040 defect
-- happened, and how this file's own packaging figure came to be computed twice
-- from two copies of one rule -- the component arithmetic moves into one
-- function. fn_variant_cost becomes a thin wrapper returning its total, and
-- the snapshot writer stores the components it returns. One implementation,
-- two callers, the same shape as fn_ingredient_cost_basis in 0034.
--
-- Snapshots written before this migration keep NULL in the new columns. That
-- is honest: detail never recorded cannot be invented afterwards. The
-- invariant is therefore "where component detail exists, it reconciles", not
-- "every snapshot has a breakdown".
-- ============================================================================

do $$
begin
  if exists (select 1 from information_schema.columns
              where table_name = 'cost_snapshots'
                and column_name in ('portion_qty_at_snapshot','variant_overhead_cost')) then
    raise exception '0046 preflight FAILED: a provenance column already exists.';
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'public' and p.proname = 'fn_confirm_order') then
    raise exception '0046 preflight FAILED: 0045 has not been applied.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0046 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- 1. The two columns
--
-- ADD COLUMN is DDL, not row mutation, so fn_block_snapshot_mutation still
-- refuses every UPDATE and DELETE on cost_snapshots exactly as before.
-- ---------------------------------------------------------------------------

alter table cost_snapshots
  add column portion_qty_at_snapshot numeric,
  add column variant_overhead_cost   numeric;

comment on column cost_snapshots.portion_qty_at_snapshot is
  'The portion size in effect when this snapshot was computed. recipes.portion_qty '
  'can change afterwards; this cannot.';

comment on column cost_snapshots.variant_overhead_cost is
  'The overhead share carried by this variant''s sold unit. NULL on snapshots '
  'written before 0046, and on recipe-level snapshots, which record overhead '
  'in overhead_cost instead.';

-- ---------------------------------------------------------------------------
-- 2. One implementation of a variant's component costs
--
-- Same arithmetic fn_variant_cost has always performed, in one place, now
-- reporting the parts as well as the sum.
--
-- One deliberate change of behaviour: packaging comes back NULL, not 0, when a
-- cost-bearing packaging item has no price. sum() skips NULLs, so the old
-- expression reported an understated packaging figure for a variant that was
-- already blocked. A cost that is not known is not zero -- that rule does not
-- stop applying because the row happens to be incomplete.
-- ---------------------------------------------------------------------------

do $$
begin
  if not exists (select 1 from pg_type where typname = 'variant_cost_components') then
    create type variant_cost_components as (
      resolved_qty       numeric,
      ingredients_labour numeric,
      packaging          numeric,
      overhead           numeric,
      total              numeric
    );
  end if;
end
$$;

create or replace function fn_variant_cost_components(p_variant_id uuid)
returns variant_cost_components
language plpgsql
stable
security definer
set search_path to 'public'
as $fn$
declare
  v record; c variant_cost_components;
  v_cpyu numeric; v_oh_rate numeric; v_unpriced_pack int;
begin
  c := row(null, null, null, null, null)::variant_cost_components;

  select rv.account_id, rv.business_id, rv.recipe_id, rv.format_id,
         r.yield_unit_id
    into v
    from recipe_variants rv
    join recipes r on r.id = rv.recipe_id
   where rv.id = p_variant_id;

  if v is null then return c; end if;
  perform fn_require_cost_access(v.account_id);

  c.resolved_qty := fn_variant_resolved_qty(p_variant_id);

  -- D4: format packaging is consumed once per sold unit and is NOT multiplied
  -- by the resolved quantity. No cost-bearing rows means no cost -- a true
  -- zero. An unpriced cost-bearing row means the figure is unknown.
  select count(*) into v_unpriced_pack
    from serving_format_packaging spk
   where spk.format_id = v.format_id
     and spk.is_cost_bearing
     and fn_ingredient_usable_unit_cost(spk.packaging_item_id, v.business_id) is null;

  if v_unpriced_pack = 0 then
    select coalesce(sum(spk.qty * fn_ingredient_usable_unit_cost(
                          spk.packaging_item_id, v.business_id)), 0)
      into c.packaging
      from serving_format_packaging spk
     where spk.format_id = v.format_id
       and spk.is_cost_bearing;
  end if;

  -- the existing engine's figure, unchanged: it already carries ingredients,
  -- sub-recipes, purchase yield, cooking yield and labour over effective yield
  select cost_per_yield_unit into v_cpyu
    from cost_snapshots
   where recipe_id = v.recipe_id and variant_id is null
   order by computed_at desc, seq desc
   limit 1;

  if v_cpyu is not null and c.resolved_qty is not null then
    c.ingredients_labour := v_cpyu * c.resolved_qty;
  end if;

  -- D1: overhead scales with output
  v_oh_rate := fn_overhead_rate(v.business_id, v.yield_unit_id);
  if v_oh_rate is null then
    if (select overhead_enabled from business_settings where business_id = v.business_id) then
      c.overhead := null;   -- enabled but unresolvable: incomplete, never zero
    else
      c.overhead := 0;      -- genuinely disabled: a true zero
    end if;
  elsif c.resolved_qty is not null then
    c.overhead := v_oh_rate * c.resolved_qty;
  end if;

  -- The total is the sum only when the variant resolves cleanly and every
  -- component is known. Anything else is not a cost.
  if fn_variant_problem(p_variant_id) is null
     and c.ingredients_labour is not null
     and c.packaging is not null
     and c.overhead is not null then
    c.total := c.ingredients_labour + c.packaging + c.overhead;
  end if;

  return c;
end
$fn$;

comment on function fn_variant_cost_components(uuid) is
  'What a sold unit of this variant costs, broken into ingredients-and-labour, '
  'packaging and overhead, plus the total. The single implementation behind '
  'both fn_variant_cost and fn_compute_variant_cost_snapshot.';

grant execute on function fn_variant_cost_components(uuid) to authenticated;

-- fn_variant_cost keeps its meaning exactly; it is now the total of the above.
create or replace function fn_variant_cost(p_variant_id uuid)
returns numeric
language plpgsql
stable
security definer
set search_path to 'public'
as $fn$
begin
  return (fn_variant_cost_components(p_variant_id)).total;
end
$fn$;

-- ---------------------------------------------------------------------------
-- 3. The snapshot writer stores the components rather than recomputing them
-- ---------------------------------------------------------------------------

create or replace function fn_compute_variant_cost_snapshot(
  p_variant_id uuid,
  p_as_of      date default current_date)
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $fn$
declare
  v record; base cost_snapshots%rowtype; c variant_cost_components;
  v_problem text; v_complete boolean; v_unpriced jsonb; v_id uuid;
begin
  select rv.account_id, rv.business_id, rv.recipe_id, rv.format_id,
         rv.costing_basis, r.yield_unit_id
    into v
    from recipe_variants rv
    join recipes r on r.id = rv.recipe_id
   where rv.id = p_variant_id;
  if v is null then
    raise exception 'Variant % does not exist', p_variant_id;
  end if;
  perform fn_require_cost_access(v.account_id);

  select * into base from cost_snapshots
   where recipe_id = v.recipe_id and variant_id is null
   order by computed_at desc, seq desc limit 1;
  if not found then
    raise exception 'Recipe % has no cost snapshot yet. Compute the recipe '
                    'cost before the variant cost.', v.recipe_id;
  end if;

  v_problem := fn_variant_problem(p_variant_id);
  c         := fn_variant_cost_components(p_variant_id);

  -- Completeness propagates upward exactly as it does for sub-recipes: a
  -- variant is complete only if its own basis resolves AND the recipe beneath
  -- it is complete.
  v_complete := base.is_complete and v_problem is null and c.total is not null;
  v_unpriced := coalesce(base.unpriced_items, '[]'::jsonb);
  if v_problem is not null then
    v_unpriced := v_unpriced || jsonb_build_object(
      'variant_id', p_variant_id, 'problem', v_problem);
  end if;

  insert into cost_snapshots (
      account_id, business_id, recipe_id, computed_at,
      costing_method, wavg_window_days,
      is_complete, required_inputs, priced_inputs, excluded_inputs, unpriced_items,
      ingredient_cost, packaging_cost, labour_cost, overhead_cost,
      batch_cost, cost_per_yield_unit, cost_per_portion,
      floor_batch_cost, floor_cost_per_yield_unit, floor_cost_per_portion,
      created_by,
      variant_id, resolved_qty, resolved_unit_id, basis_used, format_packaging_cost,
      portion_qty_at_snapshot, variant_overhead_cost)
  values (
      v.account_id, v.business_id, v.recipe_id, now(),
      base.costing_method, base.wavg_window_days,
      v_complete, base.required_inputs, base.priced_inputs, base.excluded_inputs,
      v_unpriced,
      base.ingredient_cost, base.packaging_cost, base.labour_cost, base.overhead_cost,
      base.batch_cost, base.cost_per_yield_unit,
      c.total,                                  -- cost per SOLD UNIT, not per portion
      base.floor_batch_cost, base.floor_cost_per_yield_unit, base.floor_cost_per_portion,
      auth.uid(),
      p_variant_id, c.resolved_qty, v.yield_unit_id, v.costing_basis, c.packaging,
      -- a format-based sale has no portion; the sold unit IS the portion
      base.portion_qty_at_snapshot, c.overhead)
  returning id into v_id;

  return v_id;
end
$fn$;

-- ---------------------------------------------------------------------------
-- 4. The recipe writer records the portion size it used
--
-- Reproduced in full, with one column added to the INSERT. Nothing else in it
-- changes.
-- ---------------------------------------------------------------------------

create or replace function fn_compute_recipe_cost_snapshot(p_recipe_id uuid, p_as_of date DEFAULT CURRENT_DATE, p_created_by uuid DEFAULT auth.uid())
returns uuid
language plpgsql
security definer
set search_path to 'public'
as $fn$
declare
  r recipes%rowtype; bs business_settings%rowtype; core recipe_cost_result;
  v_overhead numeric := 0; v_oh_total numeric; v_oh_rate numeric;
  v_sold_by_format boolean;
  v_required integer; v_priced integer; v_unpriced jsonb; v_complete boolean;
  v_floor_pp numeric; v_snapshot uuid;
begin
  select * into r from recipes where id = p_recipe_id and deleted_at is null;
  if not found then raise exception 'Recipe % not found', p_recipe_id; end if;

  perform fn_require_cost_access(r.account_id);   -- AUTHORIZATION

  select * into bs from business_settings where business_id = r.business_id;
  if not found then
    raise exception 'Business settings missing for business %', r.business_id;
  end if;

  core := fn__recipe_cost_core(p_recipe_id, p_as_of, 0);

  v_required := core.required_inputs;
  v_priced   := core.priced_inputs;
  v_unpriced := core.unpriced_items;
  v_complete := core.is_complete;

  -- MODEL 1 vs MODEL 2 (owner decision, Phase 4 escalation).
  -- A recipe sold through its own business-defined formats does not need a
  -- portion size: the FORMAT is the commercial unit, and fn_variant_cost
  -- allocates the batch economics to each format. A recipe with no active
  -- sellable format is portion-based and still requires one. This is not
  -- "portion is optional" -- exactly one basis applies, and which one is
  -- determined here rather than guessed.
  select exists (
    select 1
      from recipe_variants rv
      join serving_formats sf on sf.id = rv.format_id
     where rv.recipe_id = p_recipe_id
       and rv.is_active
       and sf.is_active
  ) into v_sold_by_format;

  if bs.overhead_enabled then
    v_required := v_required + 1;

    -- 0041: the reason now comes from fn_overhead_problem, which reads each
    -- overhead item's OWN basis and falls back to the business default. The
    -- decision is made once, in one place, rather than re-derived here.
    declare v_oh_problem text;
    begin
      v_oh_problem := fn_overhead_problem(r.business_id, r.yield_unit_id);
      if v_oh_problem is not null then
        v_complete := false;
        v_unpriced := v_unpriced || jsonb_build_object(
          'recipe_id', p_recipe_id, 'business_id', r.business_id,
          'problem', v_oh_problem);
        v_overhead := null;
      else
        v_oh_rate := fn_overhead_rate(r.business_id, r.yield_unit_id);
        if r.portion_qty is null then
          -- No portion size. For a FORMAT-BASED recipe that is correct:
          -- overhead is allocated per format by fn_variant_cost as
          -- overhead_rate x resolved_qty, so there is no per-portion figure
          -- to compute and none is invented.
          v_overhead := null;
          if v_sold_by_format then
            v_priced := v_priced + 1;
          end if;
        else
          v_overhead := v_oh_rate * r.portion_qty;
          v_priced   := v_priced + 1;
        end if;
      end if;
    end;
  end if;

  if r.kind = 'dish' and not v_sold_by_format then
    -- MODEL 1, portion-based: the portion is the commercial unit, so its size
    -- is a required input.
    v_required := v_required + 1;
    if r.portion_qty is null then
      v_complete := false;
      v_unpriced := v_unpriced || jsonb_build_object(
        'recipe_id', p_recipe_id, 'problem', 'missing_portion_size');
    else
      v_priced := v_priced + 1;
    end if;
  end if;
  -- MODEL 2, format-based: no portion input is required and none is invented.
  -- Whether each format can actually be costed is decided per format by
  -- fn_variant_problem, which blocks on incompatible dimensions, missing
  -- conversions and unpriced packaging. A recipe can therefore be complete
  -- while one of its formats is not, which is the truth of the situation.

  if core.priced_inputs = 0 then
    v_floor_pp := null;
  elsif core.cost_per_yield_unit is not null and r.portion_qty is not null then
    v_floor_pp := core.cost_per_yield_unit * r.portion_qty + coalesce(v_overhead, 0);
  else
    v_floor_pp := null;
  end if;

  if jsonb_array_length(v_unpriced) > 0 then
    v_complete := false;
  end if;

  insert into cost_snapshots (
    account_id, business_id, recipe_id, computed_at,
    costing_method, wavg_window_days,
    is_complete, required_inputs, priced_inputs, excluded_inputs, unpriced_items,
    ingredient_cost, packaging_cost, labour_cost, overhead_cost,
    batch_cost, cost_per_yield_unit, cost_per_portion,
    floor_batch_cost, floor_cost_per_yield_unit, floor_cost_per_portion,
    created_by,
    portion_qty_at_snapshot)
  values (
    r.account_id, r.business_id, p_recipe_id, now(),
    bs.costing_method, bs.wavg_window_days,
    v_complete, v_required, v_priced, core.excluded_inputs, v_unpriced,
    core.ingredient_cost, core.packaging_cost, core.labour_cost, v_overhead,
    case when v_complete then core.batch_cost end,
    case when v_complete then core.cost_per_yield_unit end,
    case when v_complete then v_floor_pp end,
    case when core.priced_inputs > 0 then core.batch_cost end,
    case when core.priced_inputs > 0 then core.cost_per_yield_unit end,
    v_floor_pp,
    p_created_by,
    -- 0046: the portion size actually used, recorded so the breakdown can be
    -- rebuilt later. recipes.portion_qty is mutable; this is not.
    r.portion_qty)
  returning id into v_snapshot;

  return v_snapshot;
end;
$fn$;

-- ---------------------------------------------------------------------------
-- 5. Self-check
--
-- Asserts the reconciliation invariant on every snapshot that now carries
-- component detail, not merely that the columns exist.
-- ---------------------------------------------------------------------------

do $$
declare v_pol int; v_bad int;
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'cost_snapshots'
                    and column_name = 'portion_qty_at_snapshot')
   or not exists (select 1 from information_schema.columns
                  where table_name = 'cost_snapshots'
                    and column_name = 'variant_overhead_cost') then
    raise exception '0046 self-check FAILED: a provenance column is missing.';
  end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'public' and p.proname = 'fn_variant_cost_components') then
    raise exception '0046 self-check FAILED: fn_variant_cost_components is missing.';
  end if;

  -- Nothing already written may have moved. ADD COLUMN cannot change a value,
  -- but assert it rather than assume it.
  select count(*) into v_bad from cost_snapshots
   where portion_qty_at_snapshot is not null or variant_overhead_cost is not null;
  if v_bad > 0 then
    raise exception '0046 self-check FAILED: % pre-existing snapshot(s) gained detail.', v_bad;
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0046 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0046 OK: component provenance recorded, one implementation, 116 policies unchanged.';
end
$$;

-- ===================== 0047_sales_reporting.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0047: what the sales actually made
--
-- Requires: 0001-0046 applied.
--
-- Two defects in the existing reporting are corrected here, and both matter
-- more than the new views.
--
-- P0 -- v_sales_unified counted drafts as revenue.
--   It admitted every order whose status was not 'cancelled'. Until 0045 an
--   order was born 'confirmed', so drafts were rare and the filter looked
--   harmless. Now that an order is born a draft, an unconfirmed order would be
--   reported as money taken. Revenue is now recognised at confirmation --
--   finalised_at -- which is the same boundary that freezes the cost, so
--   revenue and COGS can never be recognised at different moments.
--
-- P1 -- gross profit credited uncosted revenue as pure profit.
--   v_profit_by_period and v_profit_by_product computed
--   revenue - coalesce(sum(cogs), 0). sum() skips NULLs, so a line with no
--   frozen cost contributed its full revenue and no cost, and the reported
--   margin rose exactly when the least was known. Gross profit is now
--   costed_revenue - cogs: margin is measured only over the sales whose cost
--   is actually known, and coverage is reported beside it so the owner can see
--   how much of the picture that is. cost_coverage_pct already existed to warn
--   about this; the profit figure itself did not listen to it.
--
-- Revenue is also now net of discounts. Gross revenue, the line discount, the
-- allocated share of the order discount and net revenue are all carried
-- separately, so a discount is visible as a decision rather than buried in a
-- smaller number.
--
-- Every view here is security_invoker: it sees exactly what its caller may
-- see, and no more. The option is restated on every single one -- CREATE OR
-- REPLACE VIEW does not preserve reloptions, and pg_views.definition does not
-- show them, so a fingerprint check cannot catch its loss. Only an explicit
-- assertion can, and tests/027 makes it.
-- ============================================================================

do $$
begin
  if not exists (select 1 from information_schema.columns
                  where table_name = 'cost_snapshots' and column_name = 'variant_overhead_cost') then
    raise exception '0047 preflight FAILED: 0046 has not been applied.';
  end if;
  if exists (select 1 from pg_views where schemaname = 'public'
              and viewname in ('v_sale_lines','v_sales_summary','v_product_performance',
                               'v_orders_attention','v_sale_cost_breakdown')) then
    raise exception '0047 preflight FAILED: one of the new views already exists.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0047 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- 1. Rebuild the shared sales grain
--
-- Dropped rather than replaced: CREATE OR REPLACE VIEW cannot reorder or
-- remove a column, and this needs both. Dropping discards grants, so every
-- grant is restated at the end of each block -- the omission that had to be
-- repaired twice in 0036 and 0042.
-- ---------------------------------------------------------------------------

drop view if exists v_dashboard_waterfall;
drop view if exists v_profit_by_product;
drop view if exists v_profit_by_period;
drop view if exists v_sales_unified;

create view v_sales_unified with (security_invoker = on) as
  -- Confirmed order lines. finalised_at is the recognition boundary: it is set
  -- in the same statement that freezes the costs, so a sale never appears in
  -- revenue before its cost is frozen.
  select ol.account_id,
         o.business_id,
         'order'::text                     as source,
         ol.id                             as record_id,
         o.id                              as order_id,
         o.order_no                        as reference,
         o.order_date                      as sale_date,
         o.channel_id,
         o.customer_id,
         ol.recipe_id,
         ol.variant_id,
         ol.qty,
         ol.unit_price,
         a.gross_revenue,
         a.line_discount,
         a.allocated_order_discount,
         a.net_revenue                     as revenue,
         ol.unit_cost_at_sale,
         ol.cost_snapshot_id,
         case when ol.unit_cost_at_sale is not null
              then round(ol.qty * ol.unit_cost_at_sale, 2) end as cogs
    from order_lines ol
    join orders o on o.id = ol.order_id
    join fn_allocate_order_discount() a on a.order_line_id = ol.id
   where o.finalised_at is not null
     and o.voided_at is null
     and o.status <> 'cancelled'

  union all

  -- A daily total. It has no draft state and no discount fields; a quick sale
  -- is recorded at the price actually taken.
  select se.account_id,
         se.business_id,
         'daily_total'::text               as source,
         se.id                             as record_id,
         null::uuid                        as order_id,
         null::text                        as reference,
         se.sale_date,
         se.channel_id,
         null::uuid                        as customer_id,
         se.recipe_id,
         se.variant_id,
         se.qty,
         se.unit_price,
         round(se.qty * se.unit_price, 2)  as gross_revenue,
         0::numeric(14,2)                  as line_discount,
         0::numeric(14,2)                  as allocated_order_discount,
         round(se.qty * se.unit_price, 2)  as revenue,
         se.unit_cost_at_sale,
         se.cost_snapshot_id,
         case when se.unit_cost_at_sale is not null
              then round(se.qty * se.unit_cost_at_sale, 2) end as cogs
    from sales_entries se
   where se.voided_at is null;

comment on view v_sales_unified is
  'Every recognised sale at line grain, from orders and daily totals alike. '
  'An order appears only once confirmed, which is the same instant its cost '
  'was frozen.';

grant select on v_sales_unified to authenticated;

-- ---------------------------------------------------------------------------
-- 2. Profit, measured only over what is actually known
-- ---------------------------------------------------------------------------

create view v_profit_by_period with (security_invoker = on) as
  select account_id,
         business_id,
         date_trunc('month', sale_date::timestamptz)::date as period,
         round(sum(revenue), 2)                            as revenue,
         round(sum(revenue) filter (where cogs is not null), 2) as costed_revenue,
         round(sum(cogs), 2)                               as cogs,
         -- Only the costed subset. Crediting uncosted revenue as pure profit
         -- would flatter the margin exactly where least is known.
         round(sum(revenue) filter (where cogs is not null) - sum(cogs), 2) as gross_profit,
         round(100.0 * (sum(revenue) filter (where cogs is not null) - sum(cogs))
               / nullif(sum(revenue) filter (where cogs is not null), 0), 2) as gross_margin_pct,
         round(100.0 * coalesce(sum(revenue) filter (where cogs is not null), 0)
               / nullif(sum(revenue), 0), 2)               as cost_coverage_pct,
         round(coalesce(sum(revenue) filter (where cogs is null), 0), 2) as revenue_without_cost
    from v_sales_unified
   group by account_id, business_id, date_trunc('month', sale_date::timestamptz);

comment on view v_profit_by_period is
  'Monthly trading. gross_profit is costed_revenue minus cogs, never revenue '
  'minus cogs: a sale with no known cost contributes to revenue and coverage, '
  'and to neither profit nor margin.';

grant select on v_profit_by_period to authenticated;

create view v_profit_by_product with (security_invoker = on) as
  select s.account_id,
         s.business_id,
         s.recipe_id,
         r.name,
         round(sum(s.qty), 3)                                as units_sold,
         round(sum(s.revenue), 2)                            as revenue,
         round(sum(s.revenue) filter (where s.cogs is not null), 2) as costed_revenue,
         round(sum(s.cogs), 2)                               as cogs,
         round(sum(s.revenue) filter (where s.cogs is not null) - sum(s.cogs), 2) as gross_profit,
         round(100.0 * (sum(s.revenue) filter (where s.cogs is not null) - sum(s.cogs))
               / nullif(sum(s.revenue) filter (where s.cogs is not null), 0), 2) as gross_margin_pct,
         round(100.0 * coalesce(sum(s.revenue) filter (where s.cogs is not null), 0)
               / nullif(sum(s.revenue), 0), 2)               as cost_coverage_pct
    from v_sales_unified s
    join recipes r on r.id = s.recipe_id
   group by s.account_id, s.business_id, s.recipe_id, r.name;

comment on view v_profit_by_product is
  'Trading by dish. Same profit rule as v_profit_by_period.';

grant select on v_profit_by_product to authenticated;

create view v_dashboard_waterfall with (security_invoker = on) as
  select business_id,
         account_id,
         period,
         revenue,
         costed_revenue,
         cogs,
         gross_profit,
         gross_margin_pct,
         cost_coverage_pct,
         revenue_without_cost,
         case
           when cost_coverage_pct is null      then 'no_sales'
           when cost_coverage_pct >= 100       then 'complete'
           when cost_coverage_pct >= 80        then 'mostly_covered'
           else 'partial'
         end as confidence
    from v_profit_by_period;

grant select on v_dashboard_waterfall to authenticated;

-- ---------------------------------------------------------------------------
-- 3. v_sale_lines -- the line an owner actually looks at
--
-- Drafts are included and labelled, because an owner building an order needs
-- to see it. Only cancelled and voided orders are excluded. A draft's revenue
-- columns are what it WOULD be worth; is_confirmed says which is which, and
-- no summary view here counts a draft.
-- ---------------------------------------------------------------------------

create view v_sale_lines with (security_invoker = on) as
  select ol.id                              as line_id,
         ol.account_id,
         ol.business_id,
         o.id                               as order_id,
         o.order_no,
         o.order_date,
         o.status                           as order_status,
         (o.finalised_at is not null)       as is_confirmed,
         o.payment_status,
         o.customer_id,
         c.name                             as customer_name,
         o.channel_id,
         ol.recipe_id,
         r.name                             as product_name,
         ol.variant_id,
         f.name                             as format_name,
         ol.description,
         ol.qty,
         ol.unit_price,
         a.gross_revenue,
         a.line_discount,
         a.allocated_order_discount,
         a.net_revenue,
         ol.unit_cost_at_sale,
         case when ol.unit_cost_at_sale is not null
              then round(ol.qty * ol.unit_cost_at_sale, 2) end as cogs,
         -- Profit only where the cost is known. Never net_revenue - 0.
         case when ol.unit_cost_at_sale is not null
              then round(a.net_revenue - ol.qty * ol.unit_cost_at_sale, 2) end as gross_profit,
         case when ol.unit_cost_at_sale is not null and a.net_revenue <> 0
              then round(100.0 * (a.net_revenue - ol.qty * ol.unit_cost_at_sale)
                         / a.net_revenue, 2) end as gross_margin_pct,
         case
           when ol.recipe_id is null              then 'no_product'
           when ol.unit_cost_at_sale is not null  then 'costed'
           when o.finalised_at is null            then 'not_costed_yet'
           else                                        'sold_without_cost'
         end                                as cost_status
    from order_lines ol
    join orders o   on o.id = ol.order_id
    join fn_allocate_order_discount() a on a.order_line_id = ol.id
    left join customers c on c.id = o.customer_id
    left join recipes r   on r.id = ol.recipe_id
    left join recipe_variants rv on rv.id = ol.variant_id
    left join serving_formats f  on f.id = rv.format_id
   where o.voided_at is null
     and o.status <> 'cancelled';

comment on view v_sale_lines is
  'Order lines with revenue, discounts, frozen cost and margin. Drafts are '
  'included and marked is_confirmed = false; cancelled and voided orders are '
  'not shown here at all -- v_voided_sales keeps those inspectable.';

grant select on v_sale_lines to authenticated;

-- ---------------------------------------------------------------------------
-- 4. v_sales_summary -- one row per trading day
--
-- The day, its week and its month are all on the row, so a caller can group at
-- any of the three without three separate views drifting apart.
-- ---------------------------------------------------------------------------

create view v_sales_summary with (security_invoker = on) as
  select account_id,
         business_id,
         sale_date,
         date_trunc('week',  sale_date::timestamptz)::date as week_start,
         date_trunc('month', sale_date::timestamptz)::date as month_start,
         count(distinct case when source = 'order' then order_id end)
           + count(*) filter (where source = 'daily_total')     as sale_count,
         round(sum(gross_revenue), 2)                           as gross_revenue,
         round(sum(line_discount + allocated_order_discount), 2) as discount_given,
         round(sum(revenue), 2)                                 as revenue,
         round(sum(revenue) filter (where cogs is not null), 2)  as costed_revenue,
         round(sum(cogs), 2)                                    as cogs,
         round(sum(revenue) filter (where cogs is not null) - sum(cogs), 2) as gross_profit,
         round(100.0 * (sum(revenue) filter (where cogs is not null) - sum(cogs))
               / nullif(sum(revenue) filter (where cogs is not null), 0), 2) as gross_margin_pct,
         round(100.0 * coalesce(sum(revenue) filter (where cogs is not null), 0)
               / nullif(sum(revenue), 0), 2)                    as cost_coverage_pct,
         round(coalesce(sum(revenue) filter (where cogs is null), 0), 2) as revenue_without_cost
    from v_sales_unified
   group by account_id, business_id, sale_date;

comment on view v_sales_summary is
  'A trading day: what was sold, what was given away in discounts, what it '
  'cost, and how much of that cost is actually known.';

grant select on v_sales_summary to authenticated;

-- ---------------------------------------------------------------------------
-- 5. v_product_performance -- what sells, and what is worth selling
--
-- At variant grain where a variant was sold, because a 2.5 litre pot and a
-- 1 litre pot are different products with different economics.
-- ---------------------------------------------------------------------------

create view v_product_performance with (security_invoker = on) as
  select s.account_id,
         s.business_id,
         s.recipe_id,
         r.name                                              as product_name,
         s.variant_id,
         f.name                                              as format_name,
         round(sum(s.qty), 3)                                as units_sold,
         round(sum(s.revenue), 2)                            as revenue,
         round(sum(s.revenue) filter (where s.cogs is not null), 2) as costed_revenue,
         round(sum(s.cogs), 2)                               as cogs,
         round(sum(s.revenue) filter (where s.cogs is not null) - sum(s.cogs), 2) as gross_profit,
         round(100.0 * (sum(s.revenue) filter (where s.cogs is not null) - sum(s.cogs))
               / nullif(sum(s.revenue) filter (where s.cogs is not null), 0), 2) as gross_margin_pct,
         round(100.0 * coalesce(sum(s.revenue) filter (where s.cogs is not null), 0)
               / nullif(sum(s.revenue), 0), 2)               as cost_coverage_pct,
         min(s.sale_date)                                    as first_sold,
         max(s.sale_date)                                    as last_sold,
         -- A verdict only where there is something to judge. An unknown margin
         -- is 'unknown', never 'healthy'.
         case
           when sum(s.revenue) filter (where s.cogs is not null) is null
             or sum(s.revenue) filter (where s.cogs is not null) = 0 then 'unknown'
           when sum(s.revenue) filter (where s.cogs is not null) - sum(s.cogs) < 0 then 'losing_money'
           when 100.0 * (sum(s.revenue) filter (where s.cogs is not null) - sum(s.cogs))
                / nullif(sum(s.revenue) filter (where s.cogs is not null), 0) < 20 then 'thin'
           else 'healthy'
         end                                                 as margin_verdict
    from v_sales_unified s
    join recipes r on r.id = s.recipe_id
    left join recipe_variants rv on rv.id = s.variant_id
    left join serving_formats f  on f.id = rv.format_id
   group by s.account_id, s.business_id, s.recipe_id, r.name, s.variant_id, f.name;

comment on view v_product_performance is
  'Sales and margin by product and, where one was sold, by serving format. '
  'margin_verdict is unknown -- not healthy -- when the cost is not known.';

grant select on v_product_performance to authenticated;

-- ---------------------------------------------------------------------------
-- 6. v_orders_attention -- orders that need the owner to do something
-- ---------------------------------------------------------------------------

create view v_orders_attention with (security_invoker = on) as
  select o.id                                as order_id,
         o.account_id,
         o.business_id,
         o.order_no,
         o.order_date,
         o.status,
         o.payment_status,
         o.customer_id,
         c.name                              as customer_name,
         l.line_count,
         l.gross_revenue,
         o.order_discount,
         l.net_revenue,
         l.lines_without_cost,
         o.amount_paid,
         round(coalesce(l.net_revenue, 0) - o.amount_paid, 2) as amount_outstanding,
         current_date - o.order_date         as days_old,
         case
           when o.finalised_at is null and l.line_count = 0 then 'empty_draft'
           when o.finalised_at is null                      then 'draft_not_confirmed'
           when l.lines_without_cost > 0                    then 'sold_without_cost'
           when o.payment_status <> 'paid'
            and current_date - o.order_date > 7             then 'unpaid_over_a_week'
           else                                                  'ok'
         end                                 as attention,
         case
           when o.finalised_at is null and l.line_count = 0
             then 'This order has nothing on it yet.'
           when o.finalised_at is null
             then 'Still a draft. Its costs are not locked in until you confirm it.'
           when l.lines_without_cost > 0
             then 'Sold, but we do not know what some of it cost you.'
           when o.payment_status <> 'paid' and current_date - o.order_date > 7
             then 'Confirmed over a week ago and still not paid in full.'
           else 'Nothing needed.'
         end                                 as what_to_do
    from orders o
    left join customers c on c.id = o.customer_id
    left join lateral (
      select count(*)                                            as line_count,
             round(sum(sl.gross_revenue), 2)                     as gross_revenue,
             round(sum(sl.net_revenue), 2)                       as net_revenue,
             count(*) filter (where sl.unit_cost_at_sale is null
                                and sl.recipe_id is not null)    as lines_without_cost
        from v_sale_lines sl
       where sl.order_id = o.id
    ) l on true
   where o.voided_at is null
     and o.status <> 'cancelled';

comment on view v_orders_attention is
  'One row per live order with what, if anything, it needs. what_to_do is '
  'written for the owner, not for a developer.';

grant select on v_orders_attention to authenticated;

-- ---------------------------------------------------------------------------
-- 7. v_sale_cost_breakdown -- why a frozen cost is what it is
--
-- Reads the snapshot frozen onto the line, never today's configuration. Where
-- a snapshot predates 0046 the component columns are NULL and reconciles is
-- NULL: detail that was never recorded is reported as missing, not as zero.
-- ---------------------------------------------------------------------------

create view v_sale_cost_breakdown with (security_invoker = on) as
  select ol.id                              as line_id,
         ol.account_id,
         ol.business_id,
         ol.order_id,
         ol.recipe_id,
         ol.variant_id,
         ol.qty,
         ol.unit_cost_at_sale,
         cs.id                              as cost_snapshot_id,
         cs.computed_at                     as cost_frozen_at,
         cs.costing_method,
         cs.basis_used,
         cs.resolved_qty,
         cs.cost_per_yield_unit,
         cs.portion_qty_at_snapshot,
         -- A variant sale carries its own packaging and overhead; a portion
         -- sale carries the recipe's.
         coalesce(cs.format_packaging_cost, cs.packaging_cost) as packaging_cost,
         coalesce(cs.variant_overhead_cost,  cs.overhead_cost)  as overhead_cost,
         case
           when cs.variant_id is not null
            and cs.cost_per_yield_unit is not null
            and cs.resolved_qty is not null
             then round(cs.cost_per_yield_unit * cs.resolved_qty, 4)
           when cs.variant_id is null
            and cs.cost_per_yield_unit is not null
            and cs.portion_qty_at_snapshot is not null
             then round(cs.cost_per_yield_unit * cs.portion_qty_at_snapshot, 4)
         end                                as ingredients_and_labour,
         cs.is_complete,
         cs.unpriced_items
    from order_lines ol
    join orders o on o.id = ol.order_id
    join cost_snapshots cs on cs.id = ol.cost_snapshot_id
   where o.voided_at is null;

comment on view v_sale_cost_breakdown is
  'The components behind a line''s frozen cost, read from the snapshot that '
  'was frozen onto it. NULL components mean detail that was never recorded, '
  'which is not the same as zero.';

grant select on v_sale_cost_breakdown to authenticated;

-- ---------------------------------------------------------------------------
-- 8. Self-check
-- ---------------------------------------------------------------------------

do $$
declare v_pol int; v_missing text;
begin
  select string_agg(v, ', ') into v_missing
    from unnest(array['v_sales_unified','v_profit_by_period','v_profit_by_product',
                      'v_dashboard_waterfall','v_sale_lines','v_sales_summary',
                      'v_product_performance','v_orders_attention',
                      'v_sale_cost_breakdown']) v
   where not exists (select 1 from pg_views where schemaname = 'public' and viewname = v);
  if v_missing is not null then
    raise exception '0047 self-check FAILED: missing view(s): %', v_missing;
  end if;

  -- Every one of them must be security_invoker. This is the check a definition
  -- fingerprint cannot make.
  select string_agg(c.relname, ', ') into v_missing
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'v'
     and c.relname in ('v_sales_unified','v_profit_by_period','v_profit_by_product',
                       'v_dashboard_waterfall','v_sale_lines','v_sales_summary',
                       'v_product_performance','v_orders_attention','v_sale_cost_breakdown')
     and not coalesce('security_invoker=on' = any(c.reloptions), false);
  if v_missing is not null then
    raise exception '0047 self-check FAILED: not security_invoker: %', v_missing;
  end if;

  -- Grants are discarded by DROP VIEW. Assert they came back.
  select string_agg(v, ', ') into v_missing
    from unnest(array['v_sales_unified','v_profit_by_period','v_profit_by_product',
                      'v_dashboard_waterfall','v_sale_lines','v_sales_summary',
                      'v_product_performance','v_orders_attention',
                      'v_sale_cost_breakdown']) v
   where not exists (select 1 from information_schema.role_table_grants g
                      where g.table_schema = 'public' and g.table_name = v
                        and g.grantee = 'authenticated' and g.privilege_type = 'SELECT');
  if v_missing is not null then
    raise exception '0047 self-check FAILED: authenticated cannot read: %', v_missing;
  end if;

  -- A draft must never appear as revenue.
  if exists (select 1 from v_sales_unified s
              join orders o on o.id = s.order_id
             where o.finalised_at is null) then
    raise exception '0047 self-check FAILED: an unconfirmed order is being reported as revenue.';
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0047 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0047 OK: revenue recognised at confirmation, profit measured only where cost is known.';
end
$$;

-- ===================== 0048_function_grant_surface.sql =====================
-- ============================================================================
-- MENU MASTER NG
-- 0048: the function grant surface, restored and kept restored
--
-- Requires: 0001-0047 applied.
--
-- 0018 removed EXECUTE on every fn_* from PUBLIC and from anon. It did that
-- once, in a loop, over the functions that existed that day. It was never an
-- invariant -- nothing re-applied it -- so every migration since has added
-- functions that arrive with PostgreSQL's default of EXECUTE to PUBLIC, and
-- PUBLIC includes anon.
--
-- Found during Phase 6 by asking a question the tests had never asked: which
-- functions can a logged-out caller execute? Eleven, of which nine were added
-- after the sweep:
--
--   fn_ingredient_cost_basis     0034
--   fn_overhead_breakdown        0041
--   fn_overhead_problem          0041
--   fn_allocate_order_discount   0044
--   fn_guard_order_discount      0044
--   fn_order_line_scope          0043
--   fn_confirm_order             0045   (already narrowed in 0045)
--   fn_frozen_sale_cost          0045   (already narrowed in 0045)
--   fn_variant_cost_components   0046
--   plus fn_guard_subscription_changes and fn_payment_failure_grace
--
-- Most were harmless in practice: a trigger function cannot be usefully called
-- by hand, and the invoker-rights ones still meet row level security. The ones
-- that mattered were SECURITY DEFINER, and the one that mattered most --
-- fn_frozen_sale_cost -- took an account id it did not check, which made it a
-- cost-reading service for anybody able to guess one. That is fixed in 0045,
-- where it was introduced.
--
-- This migration repairs the surface and, more importantly, ends the pattern:
-- tests/034 now asserts the rule on every function, so the next one added
-- without a grant line fails the suite instead of shipping.
--
-- Nothing about what an authenticated user may do changes. Only what an
-- unauthenticated one may reach.
-- ============================================================================

do $$
begin
  if not exists (select 1 from pg_views where schemaname = 'public' and viewname = 'v_sale_lines') then
    raise exception '0048 preflight FAILED: 0047 has not been applied.';
  end if;
  if (select count(*) from pg_policies where schemaname = 'public') <> 116 then
    raise exception '0048 preflight FAILED: policy count is %, expected 116.',
      (select count(*) from pg_policies where schemaname = 'public');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- 1. Remove PUBLIC and anon from every Menu Master function
--
-- Restricted to fn_* and to functions not owned by an extension, exactly as
-- 0018 was: pgcrypto's helpers and PostgREST's own pre-request hook are not
-- ours to re-privilege, and local_pre_request must stay reachable or every
-- request in the local harness stops.
-- ---------------------------------------------------------------------------

do $$
declare f record; v_n int := 0;
begin
  for f in
    select p.oid::regprocedure as sig
      from pg_proc p
     where p.pronamespace = 'public'::regnamespace
       and p.proname like 'fn\_%'
       and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  loop
    execute format('revoke all on function %s from public, anon', f.sig);
    v_n := v_n + 1;
  end loop;
  raise notice '0048: EXECUTE removed from public and anon on % function(s).', v_n;
end
$$;

-- ---------------------------------------------------------------------------
-- 2. Restore what an authenticated user must be able to call
--
-- Revoking from PUBLIC removes the privilege an authenticated caller was
-- relying on wherever it was never granted to the role directly. These are the
-- functions added since 0018 that the application, or a security_invoker view,
-- actually calls. Everything else on that list is a trigger function, which the
-- trigger mechanism invokes regardless of EXECUTE.
-- ---------------------------------------------------------------------------

grant execute on function fn_ingredient_cost_basis(uuid, uuid, date)          to authenticated;
grant execute on function fn_overhead_breakdown(uuid, uuid)                   to authenticated;
grant execute on function fn_overhead_problem(uuid, uuid)                     to authenticated;
grant execute on function fn_allocate_order_discount(uuid)                    to authenticated;
grant execute on function fn_confirm_order(uuid)                              to authenticated;
grant execute on function fn_frozen_sale_cost(uuid, uuid, uuid)               to authenticated;
grant execute on function fn_variant_cost_components(uuid)                    to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Self-check
-- ---------------------------------------------------------------------------

do $$
declare v_pol int; v_left text;
begin
  select string_agg(p.proname, ', ' order by p.proname) into v_left
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname like 'fn\_%'
     and (p.proacl is null or '=X/postgres' = any(p.proacl::text[]));
  if v_left is not null then
    raise exception '0048 self-check FAILED: still executable by public: %', v_left;
  end if;

  select string_agg(p.proname, ', ' order by p.proname) into v_left
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace
     and p.proname like 'fn\_%'
     and 'anon=X/postgres' = any(p.proacl::text[]);
  if v_left is not null then
    raise exception '0048 self-check FAILED: still executable by anon: %', v_left;
  end if;

  -- PostgREST calls this on every request. If it stops being executable the
  -- whole API stops, so it is asserted rather than assumed.
  if not has_function_privilege('authenticator', 'local_pre_request()', 'execute')
     and exists (select 1 from pg_roles where rolname = 'authenticator') then
    raise exception '0048 self-check FAILED: the pre-request hook is no longer callable.';
  end if;

  -- The functions the application and the security_invoker views call.
  select string_agg(f, ', ') into v_left
    from unnest(array[
      'fn_ingredient_cost_basis(uuid,uuid,date)', 'fn_overhead_breakdown(uuid,uuid)',
      'fn_overhead_problem(uuid,uuid)', 'fn_allocate_order_discount(uuid)',
      'fn_confirm_order(uuid)', 'fn_frozen_sale_cost(uuid,uuid,uuid)',
      'fn_variant_cost_components(uuid)']) f
   where not has_function_privilege('authenticated', f, 'execute');
  if v_left is not null then
    raise exception '0048 self-check FAILED: authenticated lost access to: %', v_left;
  end if;

  select count(*) into v_pol from pg_policies where schemaname = 'public';
  if v_pol <> 116 then
    raise exception '0048 self-check FAILED: policy count moved to %.', v_pol;
  end if;
  raise notice '0048 OK: no function is executable by public or anon, 116 policies unchanged.';
end
$$;

commit;
